INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 1, 'What is a Network', '{"id":"intro","title":"What is a Network","topic":"Introduction to Networks","pdfPage":"Page 2","pdfQuote":"A network is a set of devices (often referred to as nodes) connected by communication links. A node can be a computer, printer, or any other device capable of sending and/or receiving data generated by other nodes on the network.","explanation":"A computer network is a collection of interconnected devices that can exchange data and share resources. Each device is a node; the medium connecting them is a link. Networks can be as small as two laptops and as large as the global Internet.","keyPoints":["Two or more devices (nodes) connected by links","Purpose: share resources","Medium: copper, fiber, wireless","Internet = network of networks"],"steps":[{"title":"Two nodes","desc":"Two devices (Sender + Receiver) ready"},{"title":"Link established","desc":"Physical medium connects them"},{"title":"Protocol agreed","desc":"Rules for communication accepted"},{"title":"Message sent","desc":"Data travels Sender → Receiver"},{"title":"Acknowledgement","desc":"Receiver confirms delivery"}],"cheatcode":{"why":"Two computers needed to share files. So we linked them.","like":"Two friends talking on a string phone.","wrong":"A network needs many computers.","right":"Even TWO devices with one cable is a network.","see":["🏠 Home WiFi","🏢 Office LAN","📱 Hotspot","☁️ Internet"],"oneLine":"Two or more devices + a link = a network."},"vaathiyar":{"crash":[{"tag":"INTRO","text":"Vanakkam, students. Today we start with the very base — What is a Network? Indha word-a pala thadava kettu irupinga, but meaning theriyuma?","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px;animation:pulse 2s ease-in-out infinite\">🌐</div><div style=\"color:#2dd4bf;font-weight:900;font-size:22px;margin-top:16px\">WHAT IS A NETWORK</div><div style=\"color:#6b7280;font-size:13px;margin-top:8px\">The very first concept</div></div>","readMs":5200},{"tag":"SIMPLE DEFINITION","text":"Simple-a sollanum na — two or more devices connected by a link, so they can share data. Adhu dhaan network.","visual":"<svg viewBox=\"0 0 400 140\" style=\"width:100%;max-width:400px\"><rect x=\"40\" y=\"50\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"80\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#facc15\" font-weight=\"800\">LAPTOP</text><rect x=\"280\" y=\"50\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#22c55e\" font-weight=\"800\">PRINTER</text><line x1=\"120\" y1=\"75\" x2=\"280\" y2=\"75\" stroke=\"#2dd4bf\" stroke-width=\"3\"/><circle r=\"6\" fill=\"#facc15\"><animateMotion dur=\"1.8s\" repeatCount=\"indefinite\" path=\"M 140 75 L 260 75\"/></circle><text x=\"200\" y=\"115\" text-anchor=\"middle\" font-size=\"12\" fill=\"#cbd5e1\" font-weight=\"700\">📎 A LINK connects them</text></svg>","readMs":5000},{"tag":"EVERYDAY","text":"Your home WiFi — laptop, mobile, TV, printer. Ellam oru network. Same concept, different scale.","visual":"<div style=\"display:flex;gap:20px;justify-content:center;align-items:center;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:48px\">💻</div><div style=\"color:#cbd5e1;font-size:10px\">Laptop</div></div><div style=\"text-align:center\"><div style=\"font-size:48px\">📱</div><div style=\"color:#cbd5e1;font-size:10px\">Mobile</div></div><div style=\"text-align:center\"><div style=\"font-size:48px\">📺</div><div style=\"color:#cbd5e1;font-size:10px\">TV</div></div><div style=\"text-align:center\"><div style=\"font-size:48px\">🖨️</div><div style=\"color:#cbd5e1;font-size:10px\">Printer</div></div><div style=\"text-align:center\"><div style=\"font-size:60px\">📡</div><div style=\"color:#2dd4bf;font-weight:800;font-size:10px\">ROUTER</div></div></div>","readMs":5000},{"tag":"WHY IT MATTERS","text":"Indha concept purinjaa, adhukku mela irukkira ellaa topic-um easy aagum. Network illa-na — internet illa, WhatsApp illa, YouTube illa.","visual":"<div style=\"text-align:center;display:flex;gap:30px;justify-content:center;flex-wrap:wrap\"><div><div style=\"font-size:56px\">📧</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:8px\">Email</div></div><div><div style=\"font-size:56px\">📺</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:8px\">YouTube</div></div><div><div style=\"font-size:56px\">💬</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:8px\">WhatsApp</div></div><div><div style=\"font-size:56px\">🎮</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:8px\">Games</div></div></div>","readMs":5400},{"tag":"⚡ ONE LINE","text":"So one line la — network means devices connected to share data. Simple. Vera level base concept.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px\">🎯</div><div style=\"color:#2dd4bf;font-weight:900;font-size:18px;margin-top:20px;padding:20px 32px;background:rgba(45,212,191,.08);border:2px dashed rgba(45,212,191,.4);border-radius:16px;line-height:1.5;max-width:520px\">Devices + Links = Network</div></div>","readMs":4800}],"crashExplain":[{"h":"Why we invented it","t":"Sharing files needed walking with floppy disks. Networks made sharing instant."},{"h":"Real-world anchor","t":"Your home WiFi is a network. Every office LAN is a network. The Internet is a network of networks."},{"h":"Common trap","t":"Students think network needs many computers. Even 2 devices count."}],"compare":{"left":"Network","right":"Distributed System","rows":[["Definition","Devices connected to share data","Independent computers look like ONE system"],["Example","Home WiFi, Office LAN","World Wide Web"],["Middleware","Not needed","Needed — sits on top of OS"],["User view","Sees separate machines","Sees one coherent system"]],"bars":[{"label":"Complexity","leftPct":35,"rightPct":95,"leftTxt":"Low","rightTxt":"High"},{"label":"Transparency","leftPct":20,"rightPct":100,"leftTxt":"Visible","rightTxt":"Hidden"},{"label":"Common use","leftPct":100,"rightPct":40,"leftTxt":"Everywhere","rightTxt":"Specialised"},{"label":"Setup cost","leftPct":30,"rightPct":85,"leftTxt":"₹","rightTxt":"₹₹₹"}]},"compareExplain":[{"h":"Key difference","t":"A network is what you see — separate computers. A distributed system is what users THINK they see — one big machine."},{"h":"Why it matters","t":"Exams ask this distinction. Remember: middleware is the glue that makes a distributed system."},{"h":"Real example","t":"The Web runs ON TOP of the Internet. The Internet is a network; the Web is a distributed system."}],"solve":{"q":"A network has 5 nodes connected in a full mesh. How many links are needed?","steps":[{"label":"STEP 1 — FORMULA","math":"Links = n(n−1)/2","note":"Full mesh formula"},{"label":"STEP 2 — GIVEN","math":"n = 5 nodes","note":"Each node connects to all others"},{"label":"STEP 3 — SUBSTITUTE","math":"Links = 5 × 4 / 2","note":"Insert n = 5"},{"label":"STEP 4 — CALCULATE","math":"Links = 20 / 2 = 10","note":"Simple arithmetic"},{"label":"ANSWER","math":"10 links","note":"For a 5-node full mesh"}]},"solveExplain":[{"h":"What is n?","t":"n is the number of nodes in the network. Here n = 5."},{"h":"Why divide by 2?","t":"If you just multiply 5 × 4 = 20, each link is counted twice (A→B and B→A). Divide by 2 to get the true count."},{"h":"Why this formula?","t":"Every node links to n−1 others. Total = n(n−1). Divide by 2 for double-counting."},{"h":"Why units matter?","t":"n must be a count (integer). Fractional nodes make no sense."},{"h":"How values change answer?","t":"Double n → 4× the links. Grows quadratically."}],"life":[{"ic":"🏠","h":"Home WiFi","t":"Laptop, mobile, TV, printer all connected to one router."},{"ic":"🏢","h":"Office LAN","t":"Every desk computer connects to the office switch."},{"ic":"🏧","h":"ATM Network","t":"Your bank ATM talks to a central server."},{"ic":"📱","h":"Mobile Data","t":"Your phone talks to cell towers — a wireless network."},{"ic":"🎮","h":"Online Gaming","t":"Your console connects to game servers and other players."},{"ic":"🛰️","h":"GPS","t":"Satellites form a network to locate your position."}],"lifeExplain":[{"h":"Same concept, everywhere","t":"Every modern device is part of a network. Understanding the base concept unlocks all of them."},{"h":"Scale doesn''t change the idea","t":"Two laptops or a billion devices — the concept is identical."}],"history":[{"yr":"1969","h":"ARPANET Born","t":"First network — 4 universities connected. The seed of the Internet."},{"yr":"1972","h":"First Email","t":"Ray Tomlinson sent the first email. The @ symbol was chosen."},{"yr":"1983","h":"TCP/IP Standard","t":"Vint Cerf and Bob Kahn — the protocol that runs the modern Internet."},{"yr":"1989","h":"World Wide Web","t":"Tim Berners-Lee invented the Web at CERN."},{"yr":"1995","h":"Public Internet","t":"India got its first public internet connection from VSNL."},{"yr":"Today","h":"5G + IoT","t":"Billions of devices connected. Smart homes, cars, wearables."}],"historyExplain":[{"h":"Why 1969 matters","t":"Before ARPANET, computers were isolated. The idea of \"connected computers\" was revolutionary."},{"h":"India connection","t":"VSNL brought the internet to India in 1995. Before that, only a few institutions had access."},{"h":"The pattern","t":"Every decade brought more devices online. Now the network includes everything."}],"flash":[{"q":"What is a network?","a":"Two or more devices connected by links to share data."},{"q":"Minimum devices needed?","a":"Two. One cannot form a network."},{"q":"What is a node?","a":"Any device that can send or receive data on the network."},{"q":"What is a link?","a":"The communication path between two nodes."},{"q":"Is the Internet a network?","a":"Yes — a network of networks."},{"q":"What is a distributed system?","a":"Independent computers that look like one system to the user."},{"q":"What is middleware?","a":"Software layer above the OS that makes distributed systems work."},{"q":"Real example of distributed system?","a":"The World Wide Web."}],"flashExplain":[{"h":"Active recall","t":"Say the answer out loud before flipping. If wrong, revisit."},{"h":"Spaced repetition","t":"Review cards after 1 day, 3 days, 7 days — that is how memory sticks."}],"exam":[{"q":"Define a computer network. Give two examples.","a":"A collection of interconnected devices sharing data. Examples: home WiFi, office LAN."},{"q":"Difference between a network and a distributed system?","a":"In a network users see separate machines. In a distributed system users see one coherent system. Middleware bridges the gap."},{"q":"What is a node and a link?","a":"Node = a device on the network. Link = the physical or wireless path connecting two nodes."},{"q":"What is the Internet?","a":"A network of networks — hundreds of thousands of interconnected networks worldwide."},{"q":"What is middleware? Give one example.","a":"Software between OS and application that hides distribution. Example: web browser + HTTP."}],"examExplain":[{"h":"Exam pattern","t":"Definitions = 2 marks. Comparisons = 5 marks. Applications = 3 marks."},{"h":"Key trap","t":"Many students mix up network vs distributed system. Remember: middleware is the deciding factor."},{"h":"Marks strategy","t":"Lead with the definition. Then one example. Then one line on significance."}],"eli5":{"kid":"Beta, imagine two friends with toy telephones connected by a string. They can talk. That is a network.","middle":"A network is two or more devices connected so they can share data. The connection can be a cable or wireless. Even two laptops connected by a cable are a network.","engg":"A computer network is a set of autonomous computers interconnected by a single technology. Two computers are interconnected if they can exchange information. The connection medium may be copper, fiber, microwave, infrared, or satellite. The Internet is the largest example — a network of networks."},"eli5Explain":[{"h":"Why three levels?","t":"Same idea, three audiences. Brain builds understanding faster when you see the concept at multiple depths."},{"h":"How to use","t":"Read the kid version first — it seeds intuition. Then the middle for exam answer. Then the engineering version for depth."}]}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000001', 2, 'Uses of Computer Networks', '{"id":"uses","title":"Uses of Computer Networks","topic":"Uses of Networks","pdfPage":"Page 2–3","pdfQuote":"Business Applications: to distribute information throughout the company (resource sharing). Home Applications: peer-to-peer, e-commerce, entertainment. Mobile Users: texting, GPS, m-commerce, NFC. Social Issues: privacy, security, phishing, botnets.","explanation":"Networks are used in four main areas — Business (resource sharing, email, VoIP, e-commerce), Home (P2P, streaming, shopping), Mobile (GPS, m-commerce, NFC), and Social (content sharing with security concerns like phishing and botnets).","keyPoints":["Business: resource sharing, email, VoIP","Home: P2P, streaming, shopping","Mobile: GPS, m-commerce, NFC","Social: phishing, botnet attacks"],"steps":[{"title":"Business","desc":"Resource sharing in offices"},{"title":"Home","desc":"P2P + entertainment"},{"title":"Mobile","desc":"GPS, NFC, m-commerce"},{"title":"Social","desc":"Content sharing networks"},{"title":"Security risks","desc":"Phishing & botnet attacks"}],"cheatcode":{"why":"We wanted to share files, printers, and ideas without walking.","like":"WhatsApp group for the office — everyone gets the same info.","wrong":"Networks are only for the internet.","right":"Networks also run printers, cameras, ATMs, ticket machines.","see":["📧 Email","🖨️ Shared printer","🏧 ATM","📺 Smart TV"],"oneLine":"Share resources, send messages, run the world."},"vaathiyar":{"crash":[{"tag":"INTRO","text":"Vanakkam, students. Next topic — Uses of Computer Networks. Intha topic la, networks enna ellaa vishayathula use aaguthu nu paakalaam.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px;animation:pulse 2s ease-in-out infinite\">🌍</div><div style=\"color:#2dd4bf;font-weight:900;font-size:22px;margin-top:16px\">USES OF NETWORKS</div><div style=\"color:#6b7280;font-size:13px;margin-top:8px\">Where they help us daily</div></div>","readMs":5200},{"tag":"BUSINESS","text":"Business la — printer sharing, email, video calls, cloud storage. Ellaa company-um network use panraanga.","visual":"<div style=\"display:flex;gap:24px;justify-content:center;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:56px\">🖨️</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Shared printer</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">📧</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Email</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">📞</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">VoIP</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">☁️</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Cloud</div></div></div>","readMs":5000},{"tag":"HOME","text":"Home la — Netflix, YouTube, online shopping, smart home devices. Ellaa-um network-a depend aaguthu.","visual":"<div style=\"display:flex;gap:24px;justify-content:center;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:56px\">🎬</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Netflix</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">🛒</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Shopping</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">🏠</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Smart home</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">🎮</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Online games</div></div></div>","readMs":5000},{"tag":"MOBILE","text":"Mobile la — WhatsApp, GPS, mobile payments (GPay, PhonePe), NFC tap-to-pay. Ellaa-um wireless network.","visual":"<div style=\"display:flex;gap:24px;justify-content:center;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:56px\">💬</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">Chat</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">🗺️</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">GPS</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">💳</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">UPI payment</div></div><div style=\"text-align:center\"><div style=\"font-size:56px\">📡</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:6px\">NFC</div></div></div>","readMs":5000},{"tag":"⚠️ SOCIAL ISSUES","text":"Good kooda irukku, bad kooda irukku. Phishing, botnets, privacy issues. Adhu pathi theriyanum.","visual":"<div style=\"text-align:center\"><div style=\"display:flex;gap:30px;justify-content:center\"><div><div style=\"font-size:56px\">✅</div><div style=\"color:#22c55e;font-weight:800;margin-top:8px;font-size:12px\">GOOD</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:4px\">Sharing · Learning<br>Connection</div></div><div><div style=\"font-size:56px\">⚠️</div><div style=\"color:#ef4444;font-weight:800;margin-top:8px;font-size:12px\">BAD</div><div style=\"color:#cbd5e1;font-size:11px;margin-top:4px\">Phishing · Botnets<br>Privacy loss</div></div></div></div>","readMs":5400},{"tag":"⚡ ONE LINE","text":"So one line la — networks are everywhere. Business, home, mobile, social. Ellaa life-um network-a depend aaguthu.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px\">🎯</div><div style=\"color:#2dd4bf;font-weight:900;font-size:18px;margin-top:20px;padding:20px 32px;background:rgba(45,212,191,.08);border:2px dashed rgba(45,212,191,.4);border-radius:16px;line-height:1.5;max-width:520px\">Networks run modern life</div></div>","readMs":4800}],"crashExplain":[{"h":"Why study uses?","t":"Understanding where networks apply helps you appreciate the design decisions behind them."},{"h":"Real anchor","t":"Today you used at least 10 networks — WhatsApp, GPay, Maps, YouTube, and more."},{"h":"Common trap","t":"Students think networks are only for the internet. They also run printers, ATMs, CCTV, and factory machines."}],"compare":{"left":"Business Uses","right":"Home Uses","rows":[["Primary purpose","Resource sharing + productivity","Entertainment + convenience"],["Example apps","Email, VoIP, ERP, CRM","Netflix, YouTube, gaming"],["Users","Employees (many)","Family (few)"],["Reliability need","Very high — 99.9% uptime","Comfort level"]],"bars":[{"label":"Users","leftPct":100,"rightPct":30,"leftTxt":"Many","rightTxt":"Few"},{"label":"Uptime need","leftPct":100,"rightPct":40,"leftTxt":"99.9%","rightTxt":"Comfort"},{"label":"Security","leftPct":100,"rightPct":50,"leftTxt":"Critical","rightTxt":"Medium"},{"label":"Cost","leftPct":95,"rightPct":35,"leftTxt":"High","rightTxt":"Low"}]},"compareExplain":[{"h":"Same tech, different needs","t":"Business and home both use the same networks, but priorities differ."},{"h":"Why it matters","t":"Exams often ask \"compare business vs home network uses\". Focus on purpose, users, and reliability."},{"h":"Pattern","t":"Business = many users + high reliability. Home = fewer users + convenience-focused."}],"solve":{"q":"A company of 100 employees switches to VoIP. If each call needs 64 kbps and 20 calls happen at once, what total bandwidth is needed?","steps":[{"label":"STEP 1 — FORMULA","math":"Total BW = per-call BW × concurrent calls","note":"Simple multiplication"},{"label":"STEP 2 — GIVEN","math":"64 kbps per call, 20 calls","note":"Concurrent calls"},{"label":"STEP 3 — SUBSTITUTE","math":"Total = 64 × 20","note":"Insert values"},{"label":"STEP 4 — CALCULATE","math":"Total = 1280 kbps","note":"Simple math"},{"label":"ANSWER","math":"1.28 Mbps","note":"Bandwidth required"}]},"solveExplain":[{"h":"What is concurrent calls?","t":"How many calls happen at the same time. Not the total per day."},{"h":"Why per-call BW?","t":"Each VoIP call is compressed to a small bandwidth — usually 32 to 128 kbps."},{"h":"Real-world number","t":"Office internet plans are chosen based on this calculation. Small offices need 5–10 Mbps."},{"h":"Why units matter?","t":"Keep all units same. If mixing kbps and Mbps, convert first."},{"h":"How values change?","t":"Double calls → double bandwidth. Grows linearly."}],"life":[{"ic":"📧","h":"Office Email","t":"Every office uses email servers — a business network application."},{"ic":"🖨️","h":"Shared Printer","t":"One printer, ten computers — classic resource sharing."},{"ic":"📺","h":"Netflix","t":"Streaming video to millions — home entertainment at scale."},{"ic":"💳","h":"UPI Payments","t":"GPay / PhonePe use mobile networks for instant payments."},{"ic":"📞","h":"WhatsApp Call","t":"VoIP over internet — voice packets over network."},{"ic":"🎮","h":"Online Gaming","t":"Real-time data exchange between players worldwide."}],"lifeExplain":[{"h":"Ubiquity","t":"Almost everything you did today used a network. That is the point of this topic."},{"h":"Diversity","t":"From a printer to a video call — very different uses, same underlying networks."}],"history":[{"yr":"1970s","h":"Business Networks","t":"Banks and offices start using internal networks."},{"yr":"1980s","h":"Email boom","t":"Email becomes standard in companies worldwide."},{"yr":"1990s","h":"Home Internet","t":"Dial-up brings the internet to homes."},{"yr":"2000s","h":"Broadband + WiFi","t":"Always-on internet. Home networks become common."},{"yr":"2010s","h":"Mobile-first","t":"Smartphones make network access universal."},{"yr":"Today","h":"IoT Everywhere","t":"Smart homes, cars, wearables — all connected."}],"historyExplain":[{"h":"Pattern","t":"Each decade expanded the user base — from banks to homes to pockets."},{"h":"Trend","t":"More devices, more data, more uses. Exponential growth."},{"h":"India story","t":"India jumped straight to mobile — 4G before broadband reached many towns."}],"flash":[{"q":"Three main use categories?","a":"Business, Home, Mobile."},{"q":"Give a business use example.","a":"Email or resource sharing (printers, files)."},{"q":"Give a home use example.","a":"Streaming Netflix, online shopping."},{"q":"What is VoIP?","a":"Voice over IP — telephone calls over internet."},{"q":"What is NFC used for?","a":"Tap-to-pay mobile payments."},{"q":"What is phishing?","a":"A social engineering attack to steal credentials."},{"q":"What is a botnet?","a":"A network of compromised devices controlled by an attacker."},{"q":"Main social issue with networks?","a":"Privacy loss and security risks."}],"flashExplain":[{"h":"Why these cards","t":"Each card targets one category or one risk. Memorize the categories first."},{"h":"How to use","t":"Say the answer out loud before flipping. Retest in 24 hours."}],"exam":[{"q":"Explain four uses of computer networks.","a":"Business — resource sharing, email, VoIP. Home — entertainment, shopping. Mobile — GPS, payments. Social — messaging, content."},{"q":"What is VoIP? How does it work?","a":"Voice over Internet Protocol. Voice is digitized, packetized, and sent over IP networks instead of traditional phone lines."},{"q":"What is phishing? Give one prevention method.","a":"Phishing is a social engineering attack to steal credentials. Prevention: verify sender, use 2FA, never click unknown links."},{"q":"Explain business vs home network uses.","a":"Business: many users, high reliability, resource sharing. Home: fewer users, entertainment-focused, lower cost."},{"q":"What is m-commerce? Give two examples.","a":"Mobile commerce — buying goods via mobile apps. Examples: UPI payments, Amazon app orders."}],"examExplain":[{"h":"Exam pattern","t":"Usually asks for 3–4 uses with examples. Structure answer by category."},{"h":"Common trap","t":"Students list uses without examples. Always add one — it earns extra marks."},{"h":"Marks strategy","t":"Categorize first (business/home/mobile/social), then give one example per category."}],"eli5":{"kid":"Beta, imagine you share your chocolate with friends — that is a network. Or you call grandma — that is a network too.","middle":"Computer networks are used in business (email, printers), home (streaming, shopping), mobile (GPS, payments), and social (chat, content sharing).","engg":"Computer networks are applied in four broad categories: business applications (resource sharing, client-server, VoIP, e-commerce), home applications (P2P, streaming, online shopping), mobile applications (texting, GPS, m-commerce, NFC), and social applications (content sharing, instant messaging), each with distinct reliability, security, and usability requirements."},"eli5Explain":[{"h":"Why three levels","t":"Kid version gives intuition. Middle gives exam answer. Engineering gives depth."},{"h":"How to use","t":"Read all three. It builds layered understanding in 60 seconds."}]}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000001', 3, 'Data Flow & Criteria', '{"id":"dataflow","title":"Data Flow & Criteria","topic":"Data Flow","pdfPage":"Page 4–6","pdfQuote":"Communication between two devices can be simplex, half-duplex, or full-duplex. A network must meet three criteria: performance, reliability, and security.","explanation":"Data flow has 3 modes — Simplex (one-way, keyboard→computer), Half-Duplex (both ways, take turns, walkie-talkie), Full-Duplex (both ways simultaneously, telephone). Network criteria: performance, reliability, security.","keyPoints":["Simplex: one direction only","Half-Duplex: both directions, take turns","Full-Duplex: both directions, simultaneously","Criteria: performance, reliability, security"],"steps":[{"title":"Simplex","desc":"One-way flow only"},{"title":"Half-Duplex","desc":"Two-way, take turns"},{"title":"Full-Duplex","desc":"Two-way, simultaneous"},{"title":"Performance","desc":"Throughput and delay"},{"title":"Reliability & Security","desc":"Uptime + data protection"}],"cheatcode":{"why":"Data can go one way, both ways in turns, or both ways at once.","like":"Walkie-talkie (turns) vs phone call (both at once).","wrong":"All networks are two-way at the same time.","right":"Some are one-way (keyboard) or take turns (walkie-talkie).","see":["⌨️ Keyboard","📻 Walkie-talkie","📞 Phone call","📺 TV remote"],"oneLine":"Simplex: one way. Half: take turns. Full: both at once."},"vaathiyar":{"crash":[{"tag":"INTRO","text":"Vanakkam, students. Next — Data Flow. Communication direction patthi paakalaam. Three types — simplex, half-duplex, full-duplex.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px;animation:pulse 2s ease-in-out infinite\">↔️</div><div style=\"color:#2dd4bf;font-weight:900;font-size:22px;margin-top:16px\">DATA FLOW</div><div style=\"color:#6b7280;font-size:13px;margin-top:8px\">Direction of data movement</div></div>","readMs":5200},{"tag":"SIMPLEX","text":"Simplex — one way only. Keyboard and monitor. Nee keyboard la type pannaa, computer screen la kaattum. Reverse illa.","visual":"<svg viewBox=\"0 0 400 120\" style=\"width:100%;max-width:400px\"><rect x=\"40\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"80\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#facc15\" font-weight=\"800\">KEYBOARD</text><rect x=\"280\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"320\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#22c55e\" font-weight=\"800\">COMPUTER</text><line x1=\"120\" y1=\"60\" x2=\"280\" y2=\"60\" stroke=\"#2dd4bf\" stroke-width=\"3\"/><polygon points=\"280,60 268,54 268,66\" fill=\"#2dd4bf\"/><circle r=\"6\" fill=\"#facc15\"><animateMotion dur=\"1.6s\" repeatCount=\"indefinite\" path=\"M 140 60 L 260 60\"/></circle><text x=\"200\" y=\"95\" text-anchor=\"middle\" font-size=\"11\" fill=\"#cbd5e1\" font-weight=\"700\">ONE WAY →</text></svg>","readMs":5000},{"tag":"HALF-DUPLEX","text":"Half-duplex — both directions, but one at a time. Walkie-talkie pola. Press to talk, release to listen.","visual":"<svg viewBox=\"0 0 400 120\" style=\"width:100%;max-width:400px\"><rect x=\"40\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"80\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#facc15\" font-weight=\"800\">WALKIE A</text><rect x=\"280\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"320\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#22c55e\" font-weight=\"800\">WALKIE B</text><line x1=\"120\" y1=\"50\" x2=\"280\" y2=\"50\" stroke=\"#2dd4bf\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/><line x1=\"280\" y1=\"70\" x2=\"120\" y2=\"70\" stroke=\"#a78bfa\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/><text x=\"200\" y=\"30\" text-anchor=\"middle\" font-size=\"10\" fill=\"#2dd4bf\" font-weight=\"800\">A → B</text><text x=\"200\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#a78bfa\" font-weight=\"800\">B → A</text></svg>","readMs":5200},{"tag":"FULL-DUPLEX","text":"Full-duplex — both directions at the same time. Phone call pola. Rendu per-um onna pesalaam, onna kelkalaam.","visual":"<svg viewBox=\"0 0 400 120\" style=\"width:100%;max-width:400px\"><rect x=\"40\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"80\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#facc15\" font-weight=\"800\">PERSON A</text><rect x=\"280\" y=\"35\" width=\"80\" height=\"50\" rx=\"8\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"320\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#22c55e\" font-weight=\"800\">PERSON B</text><line x1=\"120\" y1=\"50\" x2=\"280\" y2=\"50\" stroke=\"#2dd4bf\" stroke-width=\"2.5\"/><line x1=\"280\" y1=\"70\" x2=\"120\" y2=\"70\" stroke=\"#a78bfa\" stroke-width=\"2.5\"/><circle r=\"4\" fill=\"#2dd4bf\"><animateMotion dur=\"1.4s\" repeatCount=\"indefinite\" path=\"M 140 50 L 260 50\"/></circle><circle r=\"4\" fill=\"#a78bfa\"><animateMotion dur=\"1.4s\" repeatCount=\"indefinite\" path=\"M 260 70 L 140 70\"/></circle></svg>","readMs":5200},{"tag":"⚡ ONE LINE","text":"So one line la — simplex one-way, half-duplex take turns, full-duplex both at once. Simple.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px\">🎯</div><div style=\"color:#2dd4bf;font-weight:900;font-size:16px;margin-top:20px;padding:20px 32px;background:rgba(45,212,191,.08);border:2px dashed rgba(45,212,191,.4);border-radius:16px;line-height:1.6;max-width:520px\">Simplex: 1-way<br>Half-duplex: take turns<br>Full-duplex: both at once</div></div>","readMs":5200}],"crashExplain":[{"h":"Why this matters","t":"Direction of communication decides the hardware needed and the cost. Full-duplex is more expensive but faster."},{"h":"Real anchor","t":"Keyboard (simplex), walkie-talkie (half-duplex), phone call (full-duplex)."},{"h":"Common trap","t":"Students think half-duplex is slower than full-duplex. Not always — it depends on usage."}],"compare":{"left":"Half-Duplex","right":"Full-Duplex","rows":[["Direction","Both ways — one at a time","Both ways — simultaneous"],["Example","Walkie-talkie, CB radio","Telephone, video call"],["Capacity used","Shared — turn-based","Doubled — parallel"],["Cost","Lower","Higher"]],"bars":[{"label":"Speed","leftPct":50,"rightPct":100,"leftTxt":"Shared","rightTxt":"Parallel"},{"label":"Cost","leftPct":35,"rightPct":85,"leftTxt":"₹","rightTxt":"₹₹₹"},{"label":"Latency","leftPct":70,"rightPct":25,"leftTxt":"Higher","rightTxt":"Lower"},{"label":"Common use","leftPct":55,"rightPct":100,"leftTxt":"Radio","rightTxt":"Phone"}]},"compareExplain":[{"h":"When to pick","t":"Half-duplex for cost-sensitive shared media. Full-duplex when both sides need to talk at once."},{"h":"Why full is costlier","t":"Requires separate paths or frequency bands for each direction."},{"h":"Real trade","t":"Telephone uses full-duplex. Old radios used half-duplex. Modern WiFi is full-duplex per frame."}],"solve":{"q":"A link transmits 1000 bits per second. If using half-duplex, what is the effective throughput when both sides talk equally?","steps":[{"label":"STEP 1 — FORMULA","math":"Effective = Total / 2","note":"Half the time per direction"},{"label":"STEP 2 — GIVEN","math":"Total = 1000 bps","note":"Link capacity"},{"label":"STEP 3 — SUBSTITUTE","math":"Effective = 1000 / 2","note":"Both directions equally"},{"label":"STEP 4 — CALCULATE","math":"Effective = 500 bps","note":"Each direction"},{"label":"ANSWER","math":"500 bps per direction","note":"Half-duplex throughput"}]},"solveExplain":[{"h":"Why divide by 2?","t":"In half-duplex, only one side talks at a time. If both share equally, each gets half."},{"h":"Real-world example","t":"A 100 Mbps WiFi half-duplex link gives ~50 Mbps to each direction on average."},{"h":"Why units matter","t":"Always state per-direction or total. Mixing them causes confusion."},{"h":"Full-duplex comparison","t":"Full-duplex would give 1000 bps each way — twice the throughput."},{"h":"How values change","t":"Double link → double per-direction throughput."}],"life":[{"ic":"⌨️","h":"Keyboard","t":"Simplex — sends keystrokes to computer. No reverse flow."},{"ic":"📺","h":"TV Remote","t":"Simplex — sends IR signals to TV. TV does not reply."},{"ic":"📻","h":"Walkie-Talkie","t":"Half-duplex — press to talk, release to listen."},{"ic":"📞","h":"Phone Call","t":"Full-duplex — both can talk and hear simultaneously."},{"ic":"🎥","h":"Video Call","t":"Full-duplex — camera and mic work both ways."},{"ic":"🎮","h":"Online Game","t":"Full-duplex — your input and server updates flow together."}],"lifeExplain":[{"h":"Pattern","t":"Simple devices = simplex. Push-to-talk = half. Real-time conversation = full."},{"h":"Cost vs speed","t":"Full-duplex is fastest but costly. Match the mode to your use case."}],"history":[{"yr":"1837","h":"Telegraph","t":"Simplex — one-way communication over wires."},{"yr":"1876","h":"Telephone","t":"Full-duplex — voice both directions at once. Revolution."},{"yr":"1940s","h":"Walkie-Talkie","t":"Half-duplex radio for military use."},{"yr":"1970s","h":"Ethernet","t":"Half-duplex originally. Later moved to full-duplex with switches."},{"yr":"1990s","h":"Full-Duplex Modems","t":"Home internet became simultaneous up/down."},{"yr":"Today","h":"Full-Duplex WiFi","t":"Modern WiFi is full-duplex per frame."}],"historyExplain":[{"h":"Pattern","t":"Communication started simple (simplex), evolved to bidirectional (full-duplex)."},{"h":"Why it changed","t":"Users wanted natural conversation. Full-duplex mimics face-to-face."},{"h":"Modern trend","t":"Almost all new technologies default to full-duplex."}],"flash":[{"q":"Simplex — define.","a":"One-way communication only."},{"q":"Give a simplex example.","a":"Keyboard to computer, TV remote."},{"q":"Half-duplex — define.","a":"Both directions but not at the same time."},{"q":"Give a half-duplex example.","a":"Walkie-talkie, CB radio."},{"q":"Full-duplex — define.","a":"Both directions simultaneously."},{"q":"Give a full-duplex example.","a":"Telephone, video call."},{"q":"Which is fastest?","a":"Full-duplex — parallel transmission."},{"q":"Which is cheapest?","a":"Simplex — only one direction hardware."}],"flashExplain":[{"h":"Mnemonic","t":"S = single, H = half-turn, F = full parallel."},{"h":"Exam tip","t":"Exams ask \"identify the mode for X device\". Practice the examples."}],"exam":[{"q":"Differentiate simplex, half-duplex, full-duplex with examples.","a":"Simplex: one-way (keyboard). Half-duplex: two-way take turns (walkie-talkie). Full-duplex: two-way simultaneously (phone)."},{"q":"Why is full-duplex preferred for voice calls?","a":"Because both parties can talk and listen at the same time. Natural, no waiting."},{"q":"Which mode is used in traditional Ethernet?","a":"Half-duplex originally. Modern switched Ethernet uses full-duplex."},{"q":"Explain simplex with a real example.","a":"Simplex is one-way. Example: keyboard to computer, or TV remote to TV."},{"q":"What are the criteria for choosing the mode?","a":"Direction needed, cost, hardware, application requirement (real-time vs batch)."}],"examExplain":[{"h":"Exam pattern","t":"Usually a comparison table with examples. Memorize one example per mode."},{"h":"Marks strategy","t":"Write the definition. Then draw a small diagram. Then give one example."},{"h":"Common trap","t":"Do not confuse half-duplex with simplex. Half-duplex has BOTH directions, just not at once."}],"eli5":{"kid":"Beta, three ways to talk. Simplex — only you talk. Half-duplex — you talk, then I talk, one at a time. Full-duplex — we both talk and listen at the same time.","middle":"Communication can be simplex (one-way like keyboard), half-duplex (take turns like walkie-talkie), or full-duplex (both at once like telephone). The choice depends on the application.","engg":"Data flow between two devices can be simplex (unidirectional), half-duplex (bidirectional non-simultaneous), or full-duplex (bidirectional simultaneous). Full-duplex offers the highest throughput but needs dedicated channels in each direction; simplex is cheapest but least flexible."},"eli5Explain":[{"h":"Why three levels","t":"Same concept three ways. Builds layered understanding."},{"h":"Exam use","t":"The middle version is a perfect 2-mark answer. The engineering version is a 5-mark answer."}]}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000001', 4, 'Physical Topology', '{"id":"topology","title":"Physical Topology","topic":"Types of Networks","pdfPage":"Page 7–10","pdfQuote":"The physical topology is the geometric representation of the relationship of all the links and linking devices. There are four basic topologies: mesh, star, bus, and ring.","explanation":"Topology is the layout. Mesh (every node to every other, n(n-1)/2 links, max redundancy, expensive), Star (all to central hub, SPOF at hub), Bus (1 backbone with terminators, cheap, backbone break kills all), Ring (closed loop), Hybrid (combinations).","keyPoints":["Mesh: n(n-1)/2 links, max redundancy","Star: 1 link per node, SPOF at hub","Bus: 1 backbone, terminators both ends","Ring: closed loop, one break = all down","Hybrid: star + bus etc."],"steps":[{"title":"Mesh","desc":"Every node ↔ every node"},{"title":"Star","desc":"All nodes to central hub"},{"title":"Bus","desc":"One shared backbone"},{"title":"Ring","desc":"Closed loop with repeaters"},{"title":"Hybrid","desc":"Star of bus branches"},{"title":"Compare","desc":"Cost vs redundancy"}],"cheatcode":{"why":"Different ways to lay cables give different speed and cost.","like":"Road layouts — some have one main road, some have many.","wrong":"Mesh is always the best.","right":"Mesh is costly. Star is cheaper and used everywhere.","see":["🏢 Office LAN (star)","📡 Old cable TV (bus)","🔄 Data centres (mesh)","🏫 Campus (hybrid)"],"oneLine":"Layout of cables: mesh, star, bus, ring, hybrid."},"vaathiyar":{"crash":[{"tag":"INTRO","text":"Vanakkam, students. Next topic — Physical Topology. Network-ah epdi arrange panraanga nu paakalaam. Mesh, star, bus, ring.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px;animation:pulse 2s ease-in-out infinite\">🔗</div><div style=\"color:#2dd4bf;font-weight:900;font-size:22px;margin-top:16px\">PHYSICAL TOPOLOGY</div><div style=\"color:#6b7280;font-size:13px;margin-top:8px\">How devices are wired together</div></div>","readMs":5200},{"tag":"MESH","text":"Mesh — every node connects to every other node. Fastest, most reliable, but expensive. Vera level redundancy.","visual":"<svg viewBox=\"0 0 300 200\" style=\"width:100%;max-width:300px\"><line x1=\"150\" y1=\"30\" x2=\"270\" y2=\"110\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><line x1=\"270\" y1=\"110\" x2=\"150\" y2=\"170\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"170\" x2=\"30\" y2=\"110\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"110\" x2=\"150\" y2=\"30\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"30\" x2=\"150\" y2=\"170\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"110\" x2=\"270\" y2=\"110\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><circle cx=\"150\" cy=\"30\" r=\"16\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"150\" y=\"35\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"800\">N1</text><circle cx=\"270\" cy=\"110\" r=\"16\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"270\" y=\"115\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"800\">N2</text><circle cx=\"150\" cy=\"170\" r=\"16\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"150\" y=\"175\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"800\">N3</text><circle cx=\"30\" cy=\"110\" r=\"16\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"30\" y=\"115\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"800\">N4</text></svg>","readMs":5000},{"tag":"STAR","text":"Star — all nodes connect to one central hub. Easy to manage, but if the hub fails, everything fails. Office la idhu common.","visual":"<svg viewBox=\"0 0 300 200\" style=\"width:100%;max-width:300px\"><line x1=\"150\" y1=\"100\" x2=\"50\" y2=\"40\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><line x1=\"150\" y1=\"100\" x2=\"250\" y2=\"40\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><line x1=\"150\" y1=\"100\" x2=\"50\" y2=\"160\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><line x1=\"150\" y1=\"100\" x2=\"250\" y2=\"160\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><rect x=\"120\" y=\"82\" width=\"60\" height=\"36\" rx=\"18\" fill=\"#22c55e\"/><text x=\"150\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#000\" font-weight=\"900\">HUB</text><circle cx=\"50\" cy=\"40\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"50\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">A</text><circle cx=\"250\" cy=\"40\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"250\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">B</text><circle cx=\"50\" cy=\"160\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"50\" y=\"165\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">C</text><circle cx=\"250\" cy=\"160\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"250\" y=\"165\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">D</text></svg>","readMs":5000},{"tag":"BUS","text":"Bus — one backbone cable. Ellaa node-um adha attach aagum. Cheap but backbone break aanaa ellaa-um down.","visual":"<svg viewBox=\"0 0 400 140\" style=\"width:100%;max-width:400px\"><line x1=\"30\" y1=\"80\" x2=\"370\" y2=\"80\" stroke=\"#2dd4bf\" stroke-width=\"4\"/><rect x=\"20\" y=\"72\" width=\"12\" height=\"16\" fill=\"#ef4444\"/><rect x=\"368\" y=\"72\" width=\"12\" height=\"16\" fill=\"#ef4444\"/><text x=\"26\" y=\"102\" text-anchor=\"middle\" font-size=\"8\" fill=\"#ef4444\" font-weight=\"800\">TERM</text><text x=\"374\" y=\"102\" text-anchor=\"middle\" font-size=\"8\" fill=\"#ef4444\" font-weight=\"800\">TERM</text><circle cx=\"100\" cy=\"80\" r=\"10\" fill=\"#facc15\"/><circle cx=\"200\" cy=\"80\" r=\"10\" fill=\"#facc15\"/><circle cx=\"300\" cy=\"80\" r=\"10\" fill=\"#facc15\"/><line x1=\"100\" y1=\"70\" x2=\"100\" y2=\"45\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><rect x=\"85\" y=\"25\" width=\"30\" height=\"20\" rx=\"3\" fill=\"#111a2e\" stroke=\"#2dd4bf\"/><line x1=\"200\" y1=\"70\" x2=\"200\" y2=\"45\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><rect x=\"185\" y=\"25\" width=\"30\" height=\"20\" rx=\"3\" fill=\"#111a2e\" stroke=\"#2dd4bf\"/><line x1=\"300\" y1=\"70\" x2=\"300\" y2=\"45\" stroke=\"#2dd4bf\" stroke-width=\"1.5\"/><rect x=\"285\" y=\"25\" width=\"30\" height=\"20\" rx=\"3\" fill=\"#111a2e\" stroke=\"#2dd4bf\"/></svg>","readMs":5000},{"tag":"RING","text":"Ring — closed loop. Data goes around in one direction. One break aanaa whole network down.","visual":"<svg viewBox=\"0 0 300 200\" style=\"width:100%;max-width:300px\"><circle cx=\"150\" cy=\"100\" r=\"70\" fill=\"none\" stroke=\"#2dd4bf\" stroke-width=\"2.5\"/><circle cx=\"150\" cy=\"30\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"150\" y=\"35\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">N1</text><circle cx=\"220\" cy=\"100\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"220\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">N2</text><circle cx=\"150\" cy=\"170\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"150\" y=\"175\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">N3</text><circle cx=\"80\" cy=\"100\" r=\"14\" fill=\"#111a2e\" stroke=\"#2dd4bf\" stroke-width=\"2\"/><text x=\"80\" y=\"105\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff\">N4</text><circle r=\"6\" fill=\"#facc15\"><animateMotion dur=\"3s\" repeatCount=\"indefinite\" path=\"M 150 30 A 70 70 0 1 1 149.9 30\"/></circle></svg>","readMs":5000},{"tag":"⚡ ONE LINE","text":"So one line la — mesh (expensive, redundant), star (common, SPOF), bus (cheap), ring (loop). Hybrid combines them.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px\">🎯</div><div style=\"color:#2dd4bf;font-weight:900;font-size:16px;margin-top:20px;padding:20px 32px;background:rgba(45,212,191,.08);border:2px dashed rgba(45,212,191,.4);border-radius:16px;line-height:1.6;max-width:520px\">Mesh · Star · Bus · Ring · Hybrid</div></div>","readMs":5200}],"crashExplain":[{"h":"Why topology matters","t":"The physical layout decides cost, speed, redundancy, and how easy it is to troubleshoot."},{"h":"Real anchor","t":"Office uses star. Old cable TV used bus. Data centres use mesh. Campus uses hybrid."},{"h":"Common trap","t":"Students think topology = cable type. Topology is about arrangement, not cable."}],"compare":{"left":"Star","right":"Mesh","rows":[["Links for n nodes","n","n(n−1)/2"],["Cost","Low","High"],["Redundancy","None — hub is SPOF","Very high"],["Troubleshooting","Easy","Complex"],["Common use","LANs, offices","Data centres, WAN backbones"]],"bars":[{"label":"Cost","leftPct":25,"rightPct":100,"leftTxt":"Low","rightTxt":"High"},{"label":"Redundancy","leftPct":15,"rightPct":100,"leftTxt":"None","rightTxt":"Max"},{"label":"Links (n=6)","leftPct":35,"rightPct":100,"leftTxt":"6","rightTxt":"15"},{"label":"Complexity","leftPct":25,"rightPct":95,"leftTxt":"Easy","rightTxt":"Hard"}]},"compareExplain":[{"h":"Choose by need","t":"Cost-sensitive + small network → star. High reliability + money → mesh."},{"h":"Why star is everywhere","t":"Cheap, easy to add nodes, easy to find faults. Used in every office LAN."},{"h":"Why mesh is for backbone","t":"Multiple paths mean no single failure breaks the network."}],"solve":{"q":"A full mesh has 8 nodes. How many links are needed?","steps":[{"label":"STEP 1 — FORMULA","math":"Links = n(n−1)/2","note":"Full mesh formula"},{"label":"STEP 2 — GIVEN","math":"n = 8","note":"8 nodes"},{"label":"STEP 3 — SUBSTITUTE","math":"Links = 8 × 7 / 2","note":"Insert n=8"},{"label":"STEP 4 — CALCULATE","math":"Links = 56 / 2 = 28","note":"Arithmetic"},{"label":"ANSWER","math":"28 links","note":"For 8-node full mesh"}]},"solveExplain":[{"h":"What is n?","t":"Number of nodes. Here n = 8."},{"h":"Why divide by 2?","t":"Each link counted twice. A→B and B→A are the same physical link."},{"h":"Growth rate","t":"O(n²). Doubling nodes → 4× links. Explains high cost."},{"h":"Why formula works","t":"Each node links to n−1 others. Total n(n−1). Divide by 2 to remove double-counting."},{"h":"Practical limit","t":"Full mesh is used only for small networks or backbones."}],"life":[{"ic":"🏢","h":"Office LAN","t":"Star topology with a central switch."},{"ic":"📡","h":"Data Centre","t":"Mesh topology between core switches for redundancy."},{"ic":"📺","h":"Old Cable TV","t":"Bus topology — one coaxial cable for all homes."},{"ic":"🏫","h":"Campus Network","t":"Hybrid — star + bus branches."},{"ic":"🎮","h":"LAN Party","t":"Star — all PCs connect to one switch."},{"ic":"☁️","h":"Cloud Backbone","t":"Mesh — multiple paths for high availability."}],"lifeExplain":[{"h":"Where each type lives","t":"Star for offices. Bus for old cable TV. Mesh for data centres. Hybrid for campuses."},{"h":"Why mix","t":"Cost + reliability tradeoffs. Rarely one topology alone."}],"history":[{"yr":"1960s","h":"Bus Topology","t":"Early Ethernet used bus. Simple and cheap."},{"yr":"1970s","h":"Ring Topology","t":"IBM Token Ring — reliable and ordered."},{"yr":"1980s","h":"Star Rise","t":"Central hubs became cheap. Star became dominant."},{"yr":"1990s","h":"Switched Star","t":"Switch replaced hub. Dedicated bandwidth per node."},{"yr":"2000s","h":"Mesh Backbones","t":"ISPs built mesh backbones for reliability."},{"yr":"Today","h":"Hybrid Everywhere","t":"Real networks combine 2–3 topologies."}],"historyExplain":[{"h":"Pattern","t":"Started simple (bus), evolved to reliable (mesh) and easy (star)."},{"h":"Why star won","t":"Cheap, easy to expand, easy to troubleshoot. Office-friendly."},{"h":"Modern truth","t":"Real networks are hybrid. Pure topology exists only in textbooks."}],"flash":[{"q":"Mesh formula for links?","a":"n(n−1)/2"},{"q":"Star topology SPOF?","a":"The central hub or switch."},{"q":"Bus cable ends need?","a":"Terminators at both ends."},{"q":"Ring data direction?","a":"Typically one direction (unidirectional)."},{"q":"Most common LAN topology?","a":"Star."},{"q":"Cheapest topology?","a":"Bus (single cable)."},{"q":"Most redundant topology?","a":"Full mesh."},{"q":"What is hybrid topology?","a":"A combination of two or more basic topologies."}],"flashExplain":[{"h":"Mnemonic","t":"MSBR — Mesh Star Bus Ring. Add H for Hybrid."},{"h":"Exam tip","t":"Know the formula for mesh + one example per topology."}],"exam":[{"q":"Compare mesh, star, bus, and ring topologies.","a":"Mesh: n(n−1)/2 links, high cost, high redundancy. Star: n links, SPOF at hub. Bus: 1 backbone, cheap, break = all down. Ring: closed loop, break = all down."},{"q":"How many links for a full mesh of 5 nodes?","a":"5 × 4 / 2 = 10 links."},{"q":"What happens if the central hub fails in star?","a":"The entire network goes down — hub is single point of failure."},{"q":"Why are terminators needed in bus topology?","a":"To absorb signal reflections at cable ends, preventing collisions."},{"q":"Give one real-world example of each topology.","a":"Mesh: data centres. Star: office LAN. Bus: legacy cable TV. Ring: IBM Token Ring."}],"examExplain":[{"h":"Exam pattern","t":"Usually a table comparing 4 topologies. Prepare a 5-row table."},{"h":"Marks strategy","t":"Cost, redundancy, formula, one example per topology. That covers all typical questions."},{"h":"Common trap","t":"Do not write \"star is best\" without reason. Always justify with cost/redundancy."}],"eli5":{"kid":"Beta, four ways to connect friends with ropes. Mesh — everyone holds ropes to everyone. Star — everyone holds one rope to the teacher. Bus — one long rope, everyone holds it. Ring — rope makes a circle.","middle":"Network topologies describe how devices are wired. Mesh is fully connected (expensive). Star uses a central hub (common in offices). Bus uses one shared cable (cheap). Ring connects in a loop (rare today).","engg":"Physical topologies define the geometric arrangement of links and nodes. Full mesh uses n(n−1)/2 duplex links for maximum redundancy. Star uses n links to a central hub — simple but hub-dependent. Bus uses a single backbone with terminators. Ring forms a closed loop with repeaters. Hybrid topologies combine two or more to balance cost and reliability."},"eli5Explain":[{"h":"Why visualise","t":"Topologies are easiest to understand as pictures. Draw each before exams."},{"h":"Exam shortcut","t":"Sketch + 2-line compare = full marks on topology questions."}]}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000001', 5, 'Transmission Media', '{"id":"media","title":"Transmission Media","topic":"Physical Layer","pdfPage":"Page 12–17","pdfQuote":"Guided media include twisted-pair, coaxial, and fiber-optic cable. Unguided media transport electromagnetic waves without a physical conductor — radio waves, microwaves, infrared.","explanation":"Guided (wired): Twisted-Pair (cheap, RJ45), Coaxial (BNC, cable TV), Fiber-Optic (light, huge BW, immune to EMI, 50 km without repeater). Unguided: Radio (omni-directional), Microwave (uni-directional, aligned dishes), Infrared (short-range, cannot pass walls).","keyPoints":["Twisted-Pair: 2 copper wires twisted, RJ45","Coaxial: inner + shield, BNC, cable TV","Fiber: light, huge BW, immune to EMI","Radio: omni-directional","Microwave: uni-directional, aligned","Infrared: short-range, cannot pass walls"],"steps":[{"title":"Twisted-Pair","desc":"2 copper wires twisted"},{"title":"Coaxial","desc":"Inner + outer conductor"},{"title":"Fiber","desc":"Light through glass core"},{"title":"Radio","desc":"Omni-directional"},{"title":"Microwave","desc":"Uni-directional, aligned"},{"title":"Infrared","desc":"Short-range, no walls"}],"cheatcode":{"why":"Data needs a physical path to travel.","like":"Water needs pipes. Data needs cables or air.","wrong":"All media are equally fast.","right":"Fiber is fastest. Copper is cheaper. Wireless is easiest.","see":["🔌 Ethernet cable","📡 WiFi","🛰️ Satellite","💡 Fiber to home"],"oneLine":"Cables or air — the path your data takes."},"vaathiyar":{"crash":[{"tag":"INTRO","text":"Vanakkam, students. Today we are going to learn about Transmission Media. Simple-a sollanum na — data travel panna enna use aaguthu-nu paakalaam.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px;animation:pulse 2s ease-in-out infinite\">📡</div><div style=\"color:#2dd4bf;font-weight:900;font-size:22px;margin-top:16px\">TRANSMISSION MEDIA</div><div style=\"color:#6b7280;font-size:13px;margin-top:8px\">The path your data takes</div></div>","readMs":5200},{"tag":"REAL LIFE","text":"Imagine pannunga — you want to send a letter to your friend. You can walk to their house and give it directly. That walking path is basically a cable, students.","visual":"<svg viewBox=\"0 0 400 160\" style=\"width:100%;max-width:400px\"><line x1=\"60\" y1=\"80\" x2=\"340\" y2=\"80\" stroke=\"#2dd4bf\" stroke-width=\"4\" stroke-linecap=\"round\"/><circle cx=\"60\" cy=\"80\" r=\"18\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"60\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" fill=\"#facc15\" font-weight=\"800\">A</text><circle cx=\"340\" cy=\"80\" r=\"18\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"340\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" fill=\"#22c55e\" font-weight=\"800\">B</text><circle r=\"6\" fill=\"#facc15\"><animateMotion dur=\"1.8s\" repeatCount=\"indefinite\" path=\"M 80 80 L 320 80\"/></circle><text x=\"200\" y=\"130\" text-anchor=\"middle\" font-size=\"13\" fill=\"#cbd5e1\" font-weight=\"700\">📦 Physical cable</text></svg>","readMs":5000},{"tag":"REAL LIFE","text":"Or — you can just shout the message across. That shout travels through the air. Adhu-dhaan wireless, students. No cable needed.","visual":"<svg viewBox=\"0 0 400 160\" style=\"width:100%;max-width:400px\"><circle cx=\"60\" cy=\"80\" r=\"18\" fill=\"#111a2e\" stroke=\"#facc15\" stroke-width=\"2\"/><text x=\"60\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" fill=\"#facc15\" font-weight=\"800\">A</text><circle cx=\"340\" cy=\"80\" r=\"18\" fill=\"#111a2e\" stroke=\"#22c55e\" stroke-width=\"2\"/><text x=\"340\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" fill=\"#22c55e\" font-weight=\"800\">B</text><circle cx=\"200\" cy=\"80\" r=\"24\" fill=\"none\" stroke=\"#a78bfa\" stroke-width=\"2\"><animate attributeName=\"r\" values=\"24;90;24\" dur=\"2.4s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;0;1\" dur=\"2.4s\" repeatCount=\"indefinite\"/></circle><text x=\"200\" y=\"130\" text-anchor=\"middle\" font-size=\"13\" fill=\"#cbd5e1\" font-weight=\"700\">📶 Wireless signal</text></svg>","readMs":5000},{"tag":"EVERYDAY","text":"Real life la idhu dhaan — WiFi wireless, LAN cable wired. Rendu-um already use panraanga, but different situations ku different choice.","visual":"<div style=\"display:flex;gap:60px;justify-content:center;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:72px\">📶</div><div style=\"color:#a78bfa;font-weight:900;margin-top:14px;font-size:15px\">WIRELESS</div><div style=\"color:#6b7280;font-size:11px\">WiFi · Radio · Infrared</div></div><div style=\"text-align:center\"><div style=\"font-size:72px\">🔌</div><div style=\"color:#2dd4bf;font-weight:900;margin-top:14px;font-size:15px\">WIRED</div><div style=\"color:#6b7280;font-size:11px\">Copper · Fiber</div></div></div>","readMs":5000},{"tag":"⚠️ CAREFUL","text":"Idhu important, students — ellaa media-um same speed illa. Fiber is the fastest. Copper is cheaper. Wireless is the easiest to set up.","visual":"<div style=\"display:flex;gap:20px;justify-content:center;align-items:flex-end\"><div style=\"text-align:center\"><div style=\"height:180px;width:50px;background:linear-gradient(180deg,#22c55e,#166534);border-radius:8px 8px 0 0\"></div><div style=\"margin-top:10px;color:#22c55e;font-weight:900;font-size:13px\">FIBER</div><div style=\"color:#6b7280;font-size:10px\">Fastest</div></div><div style=\"text-align:center\"><div style=\"height:120px;width:50px;background:linear-gradient(180deg,#facc15,#a16207);border-radius:8px 8px 0 0\"></div><div style=\"margin-top:10px;color:#facc15;font-weight:900;font-size:13px\">COPPER</div><div style=\"color:#6b7280;font-size:10px\">Cheaper</div></div><div style=\"text-align:center\"><div style=\"height:80px;width:50px;background:linear-gradient(180deg,#a78bfa,#6d28d9);border-radius:8px 8px 0 0\"></div><div style=\"margin-top:10px;color:#a78bfa;font-weight:900;font-size:13px\">WIRELESS</div><div style=\"color:#6b7280;font-size:10px\">Easiest</div></div></div>","readMs":5600},{"tag":"⚡ ONE LINE","text":"So one line la — cables or air, adhu dhaan the path your data takes. Simple. Semma clarify aaguthula? Now let''s see it in action.","visual":"<div style=\"text-align:center\"><div style=\"font-size:80px\">🎯</div><div style=\"color:#2dd4bf;font-weight:900;font-size:18px;margin-top:20px;padding:20px 32px;background:rgba(45,212,191,.08);border:2px dashed rgba(45,212,191,.4);border-radius:16px;line-height:1.5;max-width:520px\">Cables or air —<br>the path your data takes.</div></div>","readMs":5200}],"crashExplain":[{"h":"Why this topic matters","t":"Every network you use — WiFi, mobile, internet — runs on some transmission medium."},{"h":"Real-world anchor","t":"Your WiFi uses radio. Your LAN cable uses copper. Your TV cable uses coax."},{"h":"Common trap","t":"Students think \"wireless = slow, wired = fast\". Not true — 4G wireless beats copper."}],"compare":{"left":"Twisted-Pair","right":"Fiber-Optic","rows":[["Cost","Cheap","Expensive"],["Speed","10–1000 Mbps","10+ Gbps"],["Distance","100 m before repeater","50 km before repeater"],["EMI","Picks up noise","Immune to noise"],["Used in","LANs, telephones","Backbones, ISP"]],"bars":[{"label":"Speed","leftPct":30,"rightPct":100,"leftTxt":"1 Gbps","rightTxt":"10 Gbps"},{"label":"Distance","leftPct":15,"rightPct":100,"leftTxt":"100 m","rightTxt":"50 km"},{"label":"Cost","leftPct":20,"rightPct":90,"leftTxt":"₹","rightTxt":"₹₹₹₹"},{"label":"EMI Safe","leftPct":25,"rightPct":100,"leftTxt":"Low","rightTxt":"Perfect"}]},"compareExplain":[{"h":"When to pick twisted-pair","t":"Short distance (under 100 m), tight budget, LAN. Every office uses it."},{"h":"When to pick fiber","t":"Long distance, high speed, EMI-heavy. Every ISP and data centre uses it."},{"h":"Why the difference?","t":"Copper carries electricity — affected by noise. Fiber carries light — unaffected."}],"solve":{"q":"A network sends 200-bit frames at 2 Kb/s. Find the one-way transmission time.","steps":[{"label":"STEP 1 — FORMULA","math":"T = B / R","note":"Start with the formula"},{"label":"STEP 2 — GIVEN","math":"B = 200 bits,  R = 2000 bits/s","note":"Convert 2 Kb/s → 2000 b/s"},{"label":"STEP 3 — SUBSTITUTE","math":"T = 200 / 2000","note":"Insert values"},{"label":"STEP 4 — CALCULATE","math":"T = 0.1","note":"Simple division"},{"label":"ANSWER","math":"T = 0.1 s = 100 ms","note":"Time to send one frame"}]},"solveExplain":[{"h":"What is T?","t":"Transmission time — how long to push one frame onto the wire. Unit: seconds."},{"h":"What is B?","t":"Frame size in bits. Here B = 200 bits."},{"h":"What is R?","t":"Link speed in bits per second. Here R = 2000 b/s."},{"h":"Why this formula?","t":"T = B / R because time = amount of data ÷ flow speed."},{"h":"Why units matter?","t":"Mix Kb/s with bits → answer off by 1000×. Always convert."},{"h":"How values change answer?","t":"Double B → double T. Double R → half T."}],"life":[{"ic":"📺","h":"TV Remote","t":"Uses infrared — short range, cannot pass walls."},{"ic":"📶","h":"WiFi Router","t":"Uses radio waves in 2.4 or 5 GHz. Wireless medium."},{"ic":"🏧","h":"ATM Machine","t":"Uses fiber or copper cables to reach bank servers."},{"ic":"📱","h":"Mobile 5G","t":"Uses microwave radio waves. High bandwidth wireless."},{"ic":"🏢","h":"Office LAN","t":"Uses twisted-pair copper (Cat 6). Cheap, easy."},{"ic":"🛰️","h":"Satellite TV","t":"Uses microwave uplink/downlink to satellites."}],"lifeExplain":[{"h":"Why we mix media","t":"No single medium is best for every situation. Cost, distance, mobility, speed decide."},{"h":"The pattern","t":"Short + cheap → copper. Long + fast → fiber. Mobile → wireless."}],"history":[{"yr":"1837","h":"Telegraph","t":"Samuel Morse — first electrical long-distance communication."},{"yr":"1876","h":"Telephone","t":"Alexander Graham Bell — voice over copper twisted-pair."},{"yr":"1880s","h":"Coaxial Cable","t":"Oliver Heaviside invented coax. Better bandwidth."},{"yr":"1955","h":"Fiber Optics","t":"Narinder Singh Kapany — father of fiber optics."},{"yr":"1970s","h":"Corning Glass","t":"First low-loss optical fiber. Revolutionized long-distance."},{"yr":"Today","h":"Fibre to Home","t":"FTTH in India — Jio, Airtel. 1 Gbps to homes."}],"historyExplain":[{"h":"Why study history?","t":"Every tech exists because someone solved a problem. The why makes the what stick."},{"h":"The trend","t":"Copper → coax → fiber → wireless. Each generation solved a limit."},{"h":"Proud fact","t":"Fiber optics demonstrated by an Indian — Narinder Singh Kapany."}],"flash":[{"q":"What is a transmission medium?","a":"Physical path that carries data from sender to receiver."},{"q":"Two classes of media?","a":"Guided (wired) and Unguided (wireless)."},{"q":"Which medium is fastest?","a":"Fiber-optic — carries light, huge bandwidth."},{"q":"Which medium is immune to EMI?","a":"Fiber-optic. Carries light, not electricity."},{"q":"Twisted-pair connector?","a":"RJ45."},{"q":"Coaxial connector?","a":"BNC."},{"q":"Infrared limitation?","a":"Cannot pass walls. Short range only."},{"q":"Cheapest medium?","a":"Twisted-pair copper."}],"flashExplain":[{"h":"How to use","t":"Read the question. Say the answer out loud. Then flip. Wrong? Repeat after 10 cards."},{"h":"Why it works","t":"Spaced repetition + active recall — most proven study method."}],"exam":[{"q":"Define transmission medium. Give two examples of each class.","a":"Physical path for data. Guided: twisted-pair, coaxial, fiber. Unguided: radio, microwave, infrared."},{"q":"Compare twisted-pair and fiber-optic on cost, speed, EMI.","a":"Twisted-pair: cheap, 100 Mbps–1 Gbps, suffers EMI. Fiber: costly, 10+ Gbps, immune."},{"q":"Why does fiber allow 50 km without a repeater?","a":"Light suffers very low attenuation in glass. Copper loses signal faster."},{"q":"Explain why infrared cannot pass through walls.","a":"Very high frequency. Solid objects block it. Line-of-sight only."},{"q":"What is FTTH? Why is it important?","a":"Fiber to the Home. Direct fiber into homes. Enables 1 Gbps internet."}],"examExplain":[{"h":"Exam pattern","t":"Most questions ask definition + comparison + application. Master those three."},{"h":"Marks strategy","t":"Definitions = 2 marks. Comparisons = 5. Applications = 3. Focus first on definitions."},{"h":"Common mistake","t":"Too much writing on definitions. Keep them 1–2 lines."}],"eli5":{"kid":"Beta, imagine you send a toy to your friend. You can walk and give it — that is a cable. Or shout — that is wireless.","middle":"Transmission media are paths that carry signals. Guided uses a conductor — twisted-pair, coax, fiber. Unguided uses waves — radio, microwave, infrared.","engg":"Transmission media are classified into guided (twisted-pair, coaxial, fiber) and unguided (radio, microwave, infrared). Selection based on bandwidth, attenuation, EMI immunity, and cost. Fiber offers highest bandwidth (10+ Gbps) and 50 km reach without regeneration."},"eli5Explain":[{"h":"Why three levels?","t":"Same concept, three audiences. Brain grasps better when you see it at multiple depths."},{"h":"How to use","t":"Start at kid. Then middle. Then engineering. Build understanding step by step."}]}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000006', '20000000-0000-0000-0000-000000000001', 6, 'Data Link Layer Services', '{"id":"dll-services","title":"Data Link Layer Services","topic":"Data Link Layer","pdfPage":"Page 36–37","pdfQuote":"The Data Link Layer transforms the raw transmission facility into a link. Its services include framing, physical addressing, flow control, error control, access control, and reliable delivery.","explanation":"The DLL sits above the Physical Layer. It takes the raw bit stream and turns it into a reliable link between two adjacent nodes. 7 core services: Framing, Physical Addressing, Flow Control, Error Control, Access Control, Reliable Delivery, Half/Full Duplex.","keyPoints":["Framing: bit stream → manageable frames","Physical addressing: MAC addresses","Flow control: prevent receiver overload","Error control: detect & correct errors","Access control: who talks when on shared link"],"steps":[{"title":"Framing","desc":"Break raw bit stream into frames"},{"title":"Physical Addressing","desc":"Add sender + receiver MAC"},{"title":"Flow Control","desc":"Prevent receiver buffer overflow"},{"title":"Error Control","desc":"Detect and correct errors"},{"title":"Access Control","desc":"Coordinate shared medium access"}],"cheatcode":{"why":"Raw bits on wire are messy. The DLL cleans them up.","like":"A postman who sorts letters into clean packets.","wrong":"The DLL routes packets across the internet.","right":"The DLL only moves frames between TWO nearby devices.","see":["📶 WiFi frames","🔌 Ethernet frames","📞 DSL","📡 Bluetooth"],"oneLine":"Turns messy bits into clean frames for one hop."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000007', '20000000-0000-0000-0000-000000000002', 7, 'Framing Methods', '{"id":"framing","title":"Framing Methods","topic":"Framing","pdfPage":"Page 37–40","pdfQuote":"Four framing methods: character count, flag bytes with byte stuffing, starting and ending flags with bit stuffing, physical layer coding violations.","explanation":"Framing breaks the raw bit stream into discrete frames. Method 1 (Character Count): header specifies number of characters. Method 2 (Byte Stuffing): FLAG bytes mark start/end, ESC escapes accidental FLAGs. Method 3 (Bit Stuffing): stuff a 0 after five consecutive 1s. Method 4 (Physical Coding): use invalid codes as delimiters.","keyPoints":["Character count: header stores length","Byte stuffing: ESC before FLAG bytes","Bit stuffing: 0 after five 1s","Physical coding: use invalid codes as delimiters"],"steps":[{"title":"Character Count","desc":"Header specifies frame length"},{"title":"Byte Stuffing","desc":"FLAG + ESC escape byte"},{"title":"Bit Stuffing","desc":"Insert 0 after five 1s"},{"title":"Physical Coding","desc":"Use invalid codes as flags"}],"cheatcode":{"why":"Receiver needs to know where one packet ends and next starts.","like":"Packing boxes with labels — so each box is separate.","wrong":"Any byte can mark the end of a frame.","right":"Only special FLAG bytes do. Data cannot contain FLAGs.","see":["📶 WiFi","🔌 Ethernet","📞 Serial links","🛰️ Satellite"],"oneLine":"Wrap bits into frames. Add a FLAG to show where each ends."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000008', '20000000-0000-0000-0000-000000000002', 8, 'Error Detection', '{"id":"error-detection","title":"Error Detection","topic":"Error Control","pdfPage":"Page 65–68","pdfQuote":"Basic approach for error detection is redundancy bits. Techniques: Simple Parity, Two-dimensional Parity, Checksum, CRC.","explanation":"Error detection uses redundancy bits appended to data. Simple Parity: 1 bit makes total 1s even (or odd). Two-Dimensional Parity: parity for every row and every column (can detect AND locate). Checksum: 1''s complement addition of segments. CRC: binary division by a generator polynomial — powerful and used in Ethernet.","keyPoints":["Parity: 1 bit for even/odd 1-count","2D parity: rows + columns","Checksum: 1''s complement addition","CRC: binary division, most reliable"],"steps":[{"title":"Simple Parity","desc":"1 bit makes 1s even"},{"title":"2D Parity","desc":"Row + column parities"},{"title":"Checksum","desc":"1''s complement addition"},{"title":"CRC","desc":"Binary division by polynomial"}],"cheatcode":{"why":"Data gets damaged on the wire. We need a way to know.","like":"A receipt — compare totals and see if anything changed.","wrong":"Every error is caught.","right":"Only the errors the checksum can catch.","see":["🌐 Internet packets","💳 Card payments","📦 File downloads","🔐 HTTPS"],"oneLine":"Add extra bits so the receiver can spot damage."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000009', '20000000-0000-0000-0000-000000000002', 9, 'Hamming Code', '{"id":"hamming","title":"Hamming Code","topic":"Error Correction","pdfPage":"Page 69–72","pdfQuote":"For correcting errors, one has to know the exact position of the error. Hamming code uses the relationship between data units and redundant units: 2^r ≥ d + r + 1.","explanation":"Hamming Code corrects single-bit errors. Formula: 2^r ≥ d + r + 1 (r = parity bits, d = data bits). Example: data=1010 (d=4) → r=3 → total 7 bits. Parity bits sit at positions 1, 2, 4 (powers of 2). Each parity bit checks positions whose binary index contains that bit. The decimal value of failing parities gives the error position.","keyPoints":["Formula: 2^r ≥ d + r + 1","Parity bits at positions 1, 2, 4, 8…","Each r checks positions with that bit set","Error position = decimal of failed parities"],"steps":[{"title":"Compute r","desc":"2^r ≥ d+r+1 → r=3 for d=4"},{"title":"Place parity bits","desc":"r1 at pos 1, r2 at 2, r4 at 4"},{"title":"Calculate parities","desc":"Even parity: r1=0, r2=1, r4=0"},{"title":"Transmit","desc":"Data 1010 → 7 bits 1010100"},{"title":"Detect error","desc":"r4r2r1 = 100 → bit 4 error"}],"cheatcode":{"why":"Old radios broke bits. Hamming made a code to fix them.","like":"Autocorrect — but for 1s and 0s.","wrong":"It fixes any error.","right":"It fixes only 1-bit errors.","see":["💾 SSD","📀 CD","📡 Satellite","🧬 DNA storage"],"oneLine":"Parity bits that find AND fix the broken bit."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000010', '20000000-0000-0000-0000-000000000002', 10, 'Sliding Window Protocols', '{"id":"sliding-window","title":"Sliding Window Protocols","topic":"ARQ Protocols","pdfPage":"Page 40–49","pdfQuote":"Three sliding window protocols: Stop-and-Wait ARQ, Go-Back-N ARQ, Selective Repeat ARQ.","explanation":"ARQ (Automatic Repeat reQuest) protocols handle errors on noisy channels. Stop-and-Wait: sender sends one frame and waits for ACK (window = 1). Go-Back-N: sender sends up to N frames; if a frame is lost, resend it and all after. Selective Repeat: only the damaged frame is resent; receiver buffers out-of-order frames. SR is more efficient on noisy links but more complex.","keyPoints":["SW ARQ: window size 1, one at a time","GBN: window up to 2^m-1, cumulative ACK","SR: window = 2^(m-1), only resend damaged","Sequence numbers modulo 2^m"],"steps":[{"title":"Stop-and-Wait","desc":"Send one frame, wait for ACK"},{"title":"Timeout","desc":"Timer expires → resend frame"},{"title":"Go-Back-N","desc":"Send N frames, cumulative ACK"},{"title":"Frame lost","desc":"GBN resends all outstanding"},{"title":"Selective Repeat","desc":"Only resend the damaged frame"},{"title":"Compare","desc":"Efficiency vs complexity"}],"cheatcode":{"why":"Waiting for each ACK is slow. Send many, then check.","like":"Posting 10 letters at once instead of one-by-one.","wrong":"Sender can send endless packets without waiting.","right":"Sender can only have N packets in flight (window size).","see":["🌐 TCP","📡 Satellite links","☁️ File downloads","📶 WiFi"],"oneLine":"Send a window of packets, slide forward as ACKs arrive."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000011', '20000000-0000-0000-0000-000000000002', 11, 'ALOHA & CSMA/CD', '{"id":"multiple-access","title":"ALOHA & CSMA/CD","topic":"Multiple Access","pdfPage":"Page 49–61","pdfQuote":"Random access protocols: ALOHA, CSMA, CSMA/CD, CSMA/CA. In random access, no station is superior.","explanation":"When nodes share a link, we need a Medium Access Control (MAC) method. Pure ALOHA: send whenever, vulnerable time = 2×Tfr, max throughput 18.4%. Slotted ALOHA: send only at slot boundaries, vulnerable time = Tfr, max 36.8%. CSMA: listen before transmitting. CSMA/CD: also detect collisions and abort immediately (used in wired Ethernet). CSMA/CA: avoid collisions (used in WiFi).","keyPoints":["Pure ALOHA: vulnerable = 2×Tfr, 18.4% max","Slotted ALOHA: vulnerable = Tfr, 36.8% max","CSMA: listen before transmit","CSMA/CD: detect collision mid-transmission","CSMA/CA: avoid collisions (WiFi)"],"steps":[{"title":"Pure ALOHA","desc":"Send whenever — collisions happen"},{"title":"Vulnerable time","desc":"2 × frame time window"},{"title":"Slotted ALOHA","desc":"Send only at slot start"},{"title":"CSMA","desc":"Listen before talking"},{"title":"CSMA/CD","desc":"Detect & abort on collision"}],"cheatcode":{"why":"Many devices share one cable. They need rules to talk.","like":"Classroom — raise your hand before speaking.","wrong":"Collisions cannot happen.","right":"Collisions happen. We detect and retry.","see":["📶 WiFi","🔌 Ethernet","📱 4G/5G","📡 Satellite uplink"],"oneLine":"Listen before talking, back off if two talk at once."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000012', '20000000-0000-0000-0000-000000000002', 12, 'Network Layer Design Issues', '{"id":"nl-issues","title":"Network Layer Design Issues","topic":"Network Layer","pdfPage":"Page 79–82","pdfQuote":"Store-and-forward packet switching. Services provided to transport layer. Implementation of connectionless service. Implementation of connection-oriented service.","explanation":"The Network Layer delivers packets end-to-end across multiple hops. Two service models: datagram (connectionless, each packet routed independently) and virtual-circuit (connection-oriented, a path is set up first). Routers use store-and-forward packet switching — a packet is fully received and its checksum verified before being forwarded.","keyPoints":["Store-and-forward packet switching","Services independent of router technology","Datagram: no setup, each packet independent","Virtual circuit: path established first","Routers = forwarding + routing"],"steps":[{"title":"Host sends packet","desc":"To nearest router on LAN"},{"title":"Store","desc":"Router fully receives packet"},{"title":"Verify","desc":"Checksum checked before forwarding"},{"title":"Forward","desc":"Sent to next router on path"},{"title":"Deliver","desc":"Reaches destination host"}],"cheatcode":{"why":"Routers must decide where to send each packet.","like":"A traffic police deciding which road is fastest.","wrong":"Network layer needs a full path set up every time.","right":"Datagram mode sends each packet independently, no setup.","see":["🌐 Internet","🏢 Enterprise WAN","📡 ISP routing","📱 Mobile network"],"oneLine":"Pick the best route packet by packet."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000013', '20000000-0000-0000-0000-000000000003', 13, 'Shortest Path — Dijkstra', '{"id":"dijkstra","title":"Shortest Path — Dijkstra","topic":"Routing Algorithms","pdfPage":"Page 84–85","pdfQuote":"The idea is to build a graph of the subnet, with each node representing a router and each arc a communication line. The algorithm finds the shortest path between them.","explanation":"Dijkstra''s algorithm finds the shortest path from a source router to every other node. It maintains two sets — permanent (finalized) and tentative (candidates). At each step, the node with the smallest tentative distance is made permanent, and its neighbors are relaxed: D(v) = min(D(v), D(u) + w(u,v)).","keyPoints":["Root = source, cost 0","Each step: pick min tentative node","Relax neighbours: D(v) = min(D(v), D(u)+w)","Stop when all nodes are permanent","Produces a shortest-path tree"],"steps":[{"title":"Root A","desc":"Set D(A) = 0, others = ∞"},{"title":"Make A permanent","desc":"Examine neighbours of A"},{"title":"Relax B, C","desc":"D(B)=2, D(C)=5 via A"},{"title":"Pick min (B)","desc":"Make B permanent"},{"title":"Relax via B","desc":"D(E)=4 via B beats 6"},{"title":"Repeat","desc":"Until all permanent"}],"cheatcode":{"why":"Google Maps needs the fastest route. Dijkstra found a way.","like":"Pick the closest unvisited city. Mark it done. Repeat.","wrong":"It explores all paths.","right":"It throws away any path that is longer than current best.","see":["🗺️ Google Maps","🌐 OSPF routing","🎮 Game AI","🚗 Waze"],"oneLine":"Keep picking the closest unvisited node until done."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000014', '20000000-0000-0000-0000-000000000003', 14, 'Distance Vector Routing', '{"id":"distance-vector","title":"Distance Vector Routing","topic":"Routing Algorithms","pdfPage":"Page 86–90","pdfQuote":"Each node maintains a vector (table) of minimum distances to every node. Sharing between neighbors. Updating when a table is received.","explanation":"Distance Vector routing is decentralized. Each router knows only its immediate neighbours'' distances. Periodically (or on change) each router shares its full table with neighbours, who update: D_x(y) = min_v { c(x,v) + D_v(y) }. The classic failure mode is the count-to-infinity problem, solved by split horizon and poison reverse.","keyPoints":["Each router keeps vector of distances","Shares full table with neighbours","Update: D_x(y) = min_v { c(x,v) + D_v(y) }","Triggered + periodic updates","Slow convergence — count-to-infinity"],"steps":[{"title":"Initialize","desc":"Each node knows only neighbours"},{"title":"Share table","desc":"Send distances to neighbours"},{"title":"Receive","desc":"Neighbour advertises its table"},{"title":"Add cost","desc":"Add link cost to each entry"},{"title":"Compare","desc":"Pick smaller: old vs new"},{"title":"Update","desc":"Save improved routes"}],"cheatcode":{"why":"Routers need to know the best path without seeing the whole map.","like":"Ask your neighbours for directions, then pass it on.","wrong":"Bad news spreads fast.","right":"Bad news spreads SLOWLY — the count-to-infinity problem.","see":["🌐 RIP protocol","📡 Old networks","🏘️ Small LANs"],"oneLine":"Each router tells neighbours its distances. Take the best."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000015', '20000000-0000-0000-0000-000000000003', 15, 'Link State Routing', '{"id":"link-state","title":"Link State Routing","topic":"Routing Algorithms","pdfPage":"Page 91–93","pdfQuote":"Each node has partial knowledge: it knows the state (type, condition, and cost) of its links. The whole topology can be compiled from the partial knowledge of each node.","explanation":"Link State routing has 4 steps: (1) each node builds a Link State Packet (LSP) describing its own links, (2) LSPs are flooded to all routers, (3) each router builds a shortest-path tree using Dijkstra, (4) a routing table is derived from the tree. Fast convergence — no count-to-infinity.","keyPoints":["Each node builds its LSP","Flooding distributes LSPs","Sequence numbers reject stale LSPs","Dijkstra computes shortest path tree","Used by OSPF"],"steps":[{"title":"Build LSP","desc":"Node identity + links + seq# + age"},{"title":"Flood LSP","desc":"Send out every interface except incoming"},{"title":"Compare seq","desc":"Discard older LSPs"},{"title":"Dijkstra","desc":"Build shortest-path tree"},{"title":"Routing table","desc":"Cost + next router per destination"}],"cheatcode":{"why":"Every router needs the full map, not just rumours.","like":"Everyone shares their own street map. Merge them all.","wrong":"It floods the whole network non-stop.","right":"Floods once, then everyone runs Dijkstra locally.","see":["🌐 OSPF","🏢 Enterprise networks","☁️ Data centres"],"oneLine":"Everyone shares their links → each runs Dijkstra."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000016', '20000000-0000-0000-0000-000000000003', 16, 'Hierarchical Routing', '{"id":"hierarchical","title":"Hierarchical Routing","topic":"Routing Algorithms","pdfPage":"Page 96–97","pdfQuote":"When hierarchical routing is used, the routers are divided into regions. Each router knows all details about its own region but knows nothing about other regions.","explanation":"As networks grow, flat routing tables become too large. Hierarchical routing divides routers into regions (then clusters, zones, groups…). Each router knows its own region in detail but only aggregate routes for others. Optimal number of levels for N routers is ln N, giving about e · ln N routing entries per router.","keyPoints":["Divide routers into regions","Local detail + remote summary","Reduces table size dramatically","Optimal levels = ln N","Trade-off: longer paths"],"steps":[{"title":"Flat network","desc":"720 routers → 720 entries each"},{"title":"Split into regions","desc":"24 regions of 30 routers"},{"title":"Local entries","desc":"30 entries per router"},{"title":"Remote entries","desc":"+23 region summaries = 53 total"},{"title":"Three levels","desc":"8 clusters × 9 regions × 10 routers = 25 entries"}],"cheatcode":{"why":"Big networks have too many routes for one table.","like":"A city map — you do not memorise every street.","wrong":"Flat routing works for any size network.","right":"Flat routing breaks past a few thousand nodes.","see":["🌐 Internet backbone","🏢 Corporate WAN","📡 ISP routing","☁️ Cloud data centres"],"oneLine":"Group routers into regions. Save table space."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000017', '20000000-0000-0000-0000-000000000003', 17, 'Congestion Control', '{"id":"congestion","title":"Congestion Control","topic":"Congestion Control","pdfPage":"Page 97–101","pdfQuote":"Too many packets present in (a part of) the network causes packet delay and loss that degrades performance. This situation is called congestion.","explanation":"Congestion happens when offered load exceeds network capacity. Detection/recovery: warning bit, choke packets, load shedding. Avoidance: random early discard (RED), traffic shaping via Leaky Bucket or Token Bucket. Leaky Bucket enforces constant output. Token Bucket allows bursts up to bucket capacity.","keyPoints":["Congestion collapse: goodput drops sharply","Warning bit: piggy-backed feedback","Choke packets: slow down source","Leaky Bucket: constant rate, discards excess","Token Bucket: allows bursts, discards tokens"],"steps":[{"title":"Load increases","desc":"Offered load approaches capacity"},{"title":"Onset","desc":"Bursts fill router buffers"},{"title":"Collapse","desc":"Goodput drops drastically"},{"title":"Leaky Bucket","desc":"Enforce constant output rate"},{"title":"Token Bucket","desc":"Allow bursts up to bucket size"}],"cheatcode":{"why":"Too many packets → network slows to a crawl.","like":"Too many cars on a highway. Traffic jam.","wrong":"Adding more buffers solves it.","right":"More buffers make it WORSE — packets sit and rot.","see":["🎬 YouTube","🎮 Online games","📞 Video calls","☁️ Cloud apps"],"oneLine":"Slow the sender before the network collapses."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000018', '20000000-0000-0000-0000-000000000003', 18, 'Transport Layer Services', '{"id":"transport-services","title":"Transport Layer Services","topic":"Transport Layer","pdfPage":"Page 102–104","pdfQuote":"The transport layer builds on the network layer to provide data transport from a process on a source machine to a process on a destination machine with a desired level of reliability.","explanation":"The transport layer provides process-to-process communication (not host-to-host). Two service models: connection-oriented (TCP) and connectionless (UDP). Addressing uses port numbers (0–1023 well-known, 1024–49151 registered, 49152+ dynamic).","keyPoints":["Process-to-process, not host-to-host","TCP: connection-oriented, reliable","UDP: connectionless, unreliable","Ports identify the application endpoint","TSAP = port · NSAP = IP address"],"steps":[{"title":"Process-to-process","desc":"Endpoints are applications, not hosts"},{"title":"Port addressing","desc":"16-bit number per application"},{"title":"Connection-oriented","desc":"TCP: setup, transfer, teardown"},{"title":"Connectionless","desc":"UDP: fire and forget"},{"title":"Service primitives","desc":"LISTEN, CONNECT, SEND, RECEIVE"}],"cheatcode":{"why":"Apps need to talk to apps, not just computers.","like":"Two people (apps) calling, not two buildings (hosts).","wrong":"The network layer already handles apps.","right":"Network layer = host-to-host. Transport = process-to-process.","see":["🌐 Browsers","📧 Mail apps","💬 Chat","🎮 Games"],"oneLine":"Process-to-process delivery using ports."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000019', '20000000-0000-0000-0000-000000000004', 19, 'TCP Segment Format', '{"id":"tcp-segment","title":"TCP Segment Format","topic":"TCP","pdfPage":"Page 139–142","pdfQuote":"The segment consists of a 20- to 60-byte header. Source port address, destination port, sequence number, acknowledgment number, header length, reserved, control flags, window size, checksum, urgent pointer, options.","explanation":"A TCP segment header is 20 bytes minimum, up to 60 with options. Ports identify endpoints. Sequence and Ack numbers are byte-oriented. The 6 flags (URG, ACK, PSH, RST, SYN, FIN) control connection state.","keyPoints":["Minimum header = 20 bytes","Ports: 16 bits each","Seq/Ack: 32-bit byte counters","6 flags: URG, ACK, PSH, RST, SYN, FIN","Window: 16-bit receiver buffer size"],"steps":[{"title":"Ports","desc":"Source + destination"},{"title":"Sequence number","desc":"First byte of this segment"},{"title":"Ack number","desc":"Next byte expected"},{"title":"Control flags","desc":"SYN, ACK, FIN, RST, PSH, URG"},{"title":"Window size","desc":"Advertised receiver buffer"},{"title":"Checksum","desc":"Mandatory 16-bit"},{"title":"Options","desc":"Up to 40 bytes"}],"cheatcode":{"why":"TCP needs a header to carry control info for every chunk.","like":"An envelope with sender, receiver, sequence number, flags.","wrong":"TCP header size is fixed.","right":"TCP header is 20 bytes base, up to 60 with options.","see":["🌐 Every website","📥 Downloads","☁️ Cloud sync","📧 Email"],"oneLine":"20 to 60-byte header + payload = one TCP segment."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000020', '20000000-0000-0000-0000-000000000004', 20, 'TCP 3-Way Handshake', '{"id":"tcp-handshake","title":"TCP 3-Way Handshake","topic":"TCP Connection","pdfPage":"Page 143–146","pdfQuote":"The client sends the first segment, a SYN segment. The server sends the second segment, a SYN + ACK segment. The client sends the third segment, an ACK segment.","explanation":"TCP establishes a connection with a 3-way handshake: (1) client sends SYN with seq x, (2) server replies SYN+ACK with seq y and ack x+1, (3) client sends ACK with ack y+1. SYN flood attacks exploit the server''s resource allocation during handshake.","keyPoints":["SYN → SYN+ACK → ACK","SYN consumes 1 sequence number","Prevents old duplicates","SYN flood = DoS via half-open connections"],"steps":[{"title":"SYN","desc":"Client sends seq = x"},{"title":"SYN+ACK","desc":"Server: seq = y, ack = x+1"},{"title":"ACK","desc":"Client: ack = y+1"},{"title":"Established","desc":"Both sides can send data"}],"cheatcode":{"why":"Two computers must agree before sending real data.","like":"Phone call: \"Hello?\" — \"Hi, I hear you.\" — \"Okay, let us talk.\"","wrong":"It is safe — old messages cannot trick it.","right":"Old duplicates CAN trick it. That is why we use 3 steps.","see":["🌐 Every website","📧 Email","💬 WhatsApp","🎮 Games"],"oneLine":"SYN → SYN+ACK → ACK. Then talk."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000021', '20000000-0000-0000-0000-000000000004', 21, 'TCP Flow & Sliding Window', '{"id":"tcp-window","title":"TCP Flow & Sliding Window","topic":"TCP","pdfPage":"Page 154–163","pdfQuote":"The window size at one end is determined by the lesser of two values: receiver window (rwnd) or congestion window (cwnd).","explanation":"TCP flow control is byte-oriented. Sender may have at most min(rwnd, cwnd) bytes outstanding. rwnd = receiver buffer; cwnd = congestion limit. Nagle''s algorithm coalesces small packets; Clark''s solution prevents silly window syndrome.","keyPoints":["Byte-oriented sliding window","W_eff = min(rwnd, cwnd)","rwnd = receiver buffer","cwnd = congestion limit","Nagle + Clark prevent small-packet waste"],"steps":[{"title":"rwnd advertised","desc":"Receiver buffer size"},{"title":"cwnd computed","desc":"Network congestion limit"},{"title":"Send window","desc":"min(rwnd, cwnd)"},{"title":"Window slides","desc":"As ACKs arrive"},{"title":"Zero window","desc":"Sender pauses; probes"}],"cheatcode":{"why":"Sender must not drown the receiver.","like":"A tap that slows down when the bucket is nearly full.","wrong":"The receiver alone decides the window.","right":"The SMALLER of receiver + network limits wins.","see":["🌐 TCP apps","📥 Downloads","☁️ File sync"],"oneLine":"Window = min(rwnd, cwnd). Smaller one wins."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000022', '20000000-0000-0000-0000-000000000004', 22, 'TCP Congestion Control', '{"id":"tcp-congestion","title":"TCP Congestion Control","topic":"TCP","pdfPage":"Page 167–178","pdfQuote":"TCP congestion control is based on implementing this approach using a window called congestion window. TCP adjusts the size of the window according to the AIMD rule.","explanation":"TCP uses AIMD (Additive Increase Multiplicative Decrease). Slow start doubles cwnd each RTT until ssthresh; then additive increase (+1 per RTT). On loss, cwnd is halved. Fast Retransmit reacts to 3 duplicate ACKs without waiting for timeout.","keyPoints":["AIMD: +1 per RTT, ÷2 on loss","Slow start: exponential ramp-up","ssthresh = half cwnd on loss","Fast Retransmit: 3 dup ACKs trigger resend","cwnd resets to 1 on timeout"],"steps":[{"title":"Slow start","desc":"cwnd doubles each RTT"},{"title":"Threshold","desc":"Reach ssthresh"},{"title":"AIMD","desc":"+1 per RTT"},{"title":"Packet loss","desc":"Timeout or 3 dup ACKs"},{"title":"Multiplicative decrease","desc":"cwnd → cwnd/2"},{"title":"Sawtooth","desc":"Repeat forever"}],"cheatcode":{"why":"Sending too fast breaks the network. Slow down early.","like":"Speed up slowly. Slam brakes when trouble.","wrong":"Speed up when there is no loss.","right":"Speed up gently, then cut in HALF on loss.","see":["🎬 Netflix","📥 Downloads","☁️ Cloud storage","📞 Zoom"],"oneLine":"+1 per RTT. Halve on loss. Repeat."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000023', '20000000-0000-0000-0000-000000000004', 23, 'UDP — User Datagram Protocol', '{"id":"udp","title":"UDP — User Datagram Protocol","topic":"UDP","pdfPage":"Page 179–187","pdfQuote":"The User Datagram Protocol (UDP) is called a connectionless, unreliable transport protocol.","explanation":"UDP is minimal: 8-byte header (source port, dest port, length, checksum) plus data. No handshake, no flow control, no error recovery. Each datagram is independent. Used for DNS, DHCP, VoIP, streaming, RPC — anything where speed beats reliability.","keyPoints":["Connectionless · unreliable","8-byte header only","No flow or error control","Checksum optional","Used by DNS, VoIP, streaming, RPC"],"steps":[{"title":"8-byte header","desc":"4 fields × 16 bits"},{"title":"No connection","desc":"No handshake, no teardown"},{"title":"No flow control","desc":"No windows, no ACKs"},{"title":"No error recovery","desc":"Only checksum, silently drops bad"},{"title":"Use cases","desc":"Speed > reliability"}],"cheatcode":{"why":"Sometimes speed beats reliability.","like":"Live TV — no point resending missed frames.","wrong":"UDP is bad because it is unreliable.","right":"UDP is GOOD when a late packet is worse than a lost one.","see":["🎮 Games","📞 VoIP","📺 Live video","🌐 DNS"],"oneLine":"Fire and forget. Fast, no guarantees."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000024', '20000000-0000-0000-0000-000000000004', 24, 'DNS — Domain Name System', '{"id":"dns","title":"DNS — Domain Name System","topic":"Application Layer","pdfPage":"Page 286–307","pdfQuote":"To identify an entity, TCP/IP protocols use the IP address, which uniquely identifies the connection of a host to the Internet. However, people prefer to use names instead of numeric addresses.","explanation":"DNS is a hierarchical, distributed database that maps human-readable names (like google.com) to IP addresses. Name space is an inverted tree: root → TLD → domain → subdomain. Resolution can be recursive or iterative. Uses UDP port 53.","keyPoints":["Hierarchical name space (root → TLD → domain)","Maps names ↔ IP addresses","Uses UDP port 53","Recursive vs iterative resolution","Caching speeds up lookups"],"steps":[{"title":"Flat vs Hierarchy","desc":"Flat has no structure; hierarchy nests"},{"title":"Root level","desc":"Top of tree — delegates to TLDs"},{"title":"Query resolver","desc":"Client asks local DNS server"},{"title":"Recursive lookup","desc":"Server asks others on your behalf"},{"title":"Cache response","desc":"Store for TTL to skip future lookups"}],"cheatcode":{"why":"Humans remember names. Computers use numbers.","like":"Phone book — name → number.","wrong":"One server holds every name.","right":"It is a tree — root → TLD → domain → host.","see":["🌐 Any website","📱 Apps","📧 Email","☁️ Cloud"],"oneLine":"Translate names like google.com into IP addresses."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000025', '20000000-0000-0000-0000-000000000005', 25, 'WWW & HTTP', '{"id":"www-http","title":"WWW & HTTP","topic":"Application Layer","pdfPage":"Page 267–285","pdfQuote":"The WWW today is a distributed client/server service, in which a client using a browser can access a service using a server.","explanation":"The World Wide Web is a distributed client/server system. Clients (browsers) request documents from servers using HTTP. Documents can be static (HTML files), dynamic (generated on request — CGI/PHP/JSP), or active (run on client — JavaScript/Java). HTTP is request/response, uses TCP port 80 (443 for HTTPS).","keyPoints":["Client/server model","HTTP on TCP port 80","Static / dynamic / active documents","URL = protocol + host + port + path","HTTP/1.1 defaults to persistent connections"],"steps":[{"title":"URL","desc":"protocol + host + port + path"},{"title":"Request","desc":"GET /index.html HTTP/1.1"},{"title":"Response","desc":"200 OK + content"},{"title":"Static doc","desc":"Fixed HTML from disk"},{"title":"Dynamic doc","desc":"Server generates via CGI/PHP"}],"cheatcode":{"why":"We needed a way to share documents across the world.","like":"Order food: you ask (request), waiter brings it (response).","wrong":"HTTP remembers your last request.","right":"HTTP is stateless — cookies remember you.","see":["🌐 Browsers","📱 Apps","🛒 Shopping","☁️ APIs"],"oneLine":"Client asks, server answers. Port 80 / 443."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000026', '20000000-0000-0000-0000-000000000005', 26, 'FTP — File Transfer Protocol', '{"id":"ftp","title":"FTP — File Transfer Protocol","topic":"Application Layer","pdfPage":"Page 249–260","pdfQuote":"FTP - File Transfer Protocol - For file transfer.","explanation":"FTP transfers files between a client and a server. It uses TWO TCP connections: a control connection on port 21 (commands) and a data connection on port 20 (actual file bytes). This split design keeps commands responsive while large files transfer.","keyPoints":["Two TCP connections: control (21) + data (20)","Control connection stays open","Data connection opens per transfer","Supports ASCII and binary modes","Supports anonymous access"],"steps":[{"title":"Connect","desc":"Client opens control on port 21"},{"title":"Authenticate","desc":"USER + PASS commands"},{"title":"Command","desc":"RETR / STOR / LIST"},{"title":"Data channel","desc":"Server opens port 20"},{"title":"Transfer","desc":"File bytes streamed"},{"title":"Close","desc":"QUIT terminates both connections"}],"cheatcode":{"why":"Big files need a reliable, resumable transfer.","like":"Two phone lines — one to talk, one to send the parcel.","wrong":"FTP uses one connection.","right":"FTP uses TWO — control (21) and data (20).","see":["🏢 Office file servers","🖥️ Website uploads","💾 Backups"],"oneLine":"Command on 21. File bytes on 20."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000027', '20000000-0000-0000-0000-000000000005', 27, 'SMTP & Email', '{"id":"smtp","title":"SMTP & Email","topic":"Application Layer","pdfPage":"Page 249–260","pdfQuote":"SMTP - Simple Mail Transfer Protocol - For mail transfer.","explanation":"SMTP pushes email from sender to mail server, and between mail servers. Uses TCP port 25 (587 for submission). Only sends 7-bit ASCII; binary attachments must be encoded (MIME). POP3/IMAP are used by the client to pull mail from server. SMTP = push, POP3/IMAP = pull.","keyPoints":["SMTP sends/pushes email","TCP port 25 (587 submission)","7-bit ASCII only — MIME for attachments","POP3 (110) / IMAP (143) receive","Store-and-forward between servers"],"steps":[{"title":"Compose","desc":"User writes email in client"},{"title":"Submit","desc":"Client → sender mail server (25)"},{"title":"Relay","desc":"Sender server → recipient server"},{"title":"Store","desc":"Recipient server stores message"},{"title":"Retrieve","desc":"Client pulls via POP3 or IMAP"}],"cheatcode":{"why":"Email must move from sender to receiver, even if offline.","like":"Post office — your letter is passed between offices.","wrong":"SMTP reads your email too.","right":"SMTP SENDS only. POP3/IMAP receive.","see":["📧 Gmail","📨 Outlook","📮 Any mail app"],"oneLine":"SMTP pushes mail (port 25). POP3/IMAP pull it."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000028', '20000000-0000-0000-0000-000000000005', 28, 'TELNET & Remote Login', '{"id":"telnet","title":"TELNET & Remote Login","topic":"Application Layer","pdfPage":"Page 263–266","pdfQuote":"TELNET enables the establishment of a connection to a remote system in such a way that the local terminal appears to be a terminal at the remote system.","explanation":"TELNET is a client/server protocol for remote login. Uses TCP port 23. The client converts local keystrokes into NVT (Network Virtual Terminal) characters — a universal ASCII 7-bit encoding — which travel to the server. The server converts NVT back to the target system''s native format.","keyPoints":["Remote login protocol","TCP port 23","NVT = Network Virtual Terminal (7-bit ASCII)","Client → NVT → Server → native","Platform-independent"],"steps":[{"title":"Local terminal","desc":"User types at keyboard"},{"title":"Convert to NVT","desc":"Client sends universal 7-bit chars"},{"title":"Travel","desc":"Through TCP/IP stack to server"},{"title":"Convert from NVT","desc":"Server maps to native chars"},{"title":"Remote exec","desc":"Server runs command, returns output"}],"cheatcode":{"why":"Before SSH, we needed a way to log in remotely.","like":"A universal remote — works with any TV.","wrong":"TELNET is secure.","right":"TELNET sends plain text. Never use over the internet.","see":["🔧 Old routers","📡 Device config","💻 Local labs"],"oneLine":"Remote login on port 23. Uses NVT (7-bit ASCII)."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.topics (id, unit_id, idx, title, json, visual_type, validated) VALUES ('30000000-0000-0000-0000-000000000029', '20000000-0000-0000-0000-000000000005', 29, 'RTP — Real-time Transport', '{"id":"rtp","title":"RTP — Real-time Transport","topic":"Application Layer","pdfPage":"Page 254–262","pdfQuote":"RTP (Real-time Transport Protocol) is described in RFC 3550 and is now in widespread use for multimedia applications.","explanation":"RTP transports audio and video over UDP. Runs in user space, typically over UDP, so packets can be lost but timing is preserved. Each RTP packet carries a sequence number (to detect loss), a timestamp (for jitter reduction and sync), and an SSRC identifier (which stream). The companion protocol RTCP provides feedback.","keyPoints":["Real-time audio/video over UDP","Runs in user space","Sequence number + timestamp","SSRC = stream identifier","RTCP companion = feedback"],"steps":[{"title":"Capture","desc":"App produces audio/video frames"},{"title":"RTP encode","desc":"Add seq #, timestamp, SSRC"},{"title":"UDP wrap","desc":"Packets handed to UDP"},{"title":"Transmit","desc":"Best-effort over network"},{"title":"Playout","desc":"Receiver buffers to reduce jitter"}],"cheatcode":{"why":"Audio and video need timing, not perfection.","like":"Live cricket — a late ball is a missed ball.","wrong":"RTP resends lost packets.","right":"RTP never resends. Receiver buffers to smooth jitter.","see":["📞 VoIP","📺 IPTV","🎥 Video calls","🎙️ Podcasts"],"oneLine":"Real-time media over UDP. Sequence + timestamp."},"vaathiyar":{}}'::jsonb, 'process_flow', true) ON CONFLICT (id) DO NOTHING;
